sp:qinmian.code:
{
    audio: 2,
    trigger: {
      player: ["phaseZhunbeiBegin", "damageEnd"]
    },
    getIndex: (event2) => event2.name == "damage" ? event2.num : 1,
    check: () => true,
    frequent: true,
    async content(event2, trigger2, player2) {
      await player2.draw({
        num: 1,
        gaintag: [event2.name]
      });
    },
    group: "qinmian_damage",
    subSkill: {
      damage: {
        audio: "qinmian",
        trigger: {
          global: "phaseJieshuBegin"
        },
        filter(event2, player2) {
          return player2.hasCards("h", (card2) => card2.hasGaintag("qinmian"));
        },
        logTarget: () => _status.currentPhase,
        isAllQinmian(player2) {
          return !player2.hasCards("h", (card2) => !card2.hasGaintag("qinmian"));
        },
        prompt2(event2, player2) {
          const target2 = _status.currentPhase;
          const num = get.info("qinmian_damage").isAllQinmian(player2) ? player2.countCards("h") : 1;
          return `将所有“勤勉”牌置入弃牌堆，然后对${get.translation(target2)}造成${num}点伤害`;
        },
        check(event2, player2) {
          const target2 = _status.currentPhase;
          const cards2 = player2.getCards("h", (card2) => card2.hasGaintag("qinmian"));
          const bool = get.info("qinmian_damage").isAllQinmian(player2);
          const eff = get.damageEffect(target2, player2, player2);
          if (eff > 0) {
            if (bool) {
              return true;
            }
            if (get.value(cards2) < 7) {
              return true;
            }
          }
          return false;
        },
        async content(event2, trigger2, player2) {
          const {
            targets: [target2]
          } = event2;
          const cards2 = player2.getCards("h", (card2) => card2.hasGaintag("qinmian"));
          const bool = get.info("qinmian_damage").isAllQinmian(player2);
          await player2.loseToDiscardpile({ cards: cards2 });
          await target2.damage({ num: bool ? cards2.length : 1 });
        }
      }
    }
  }

