sp:olyanjing.code:
{
    audio: 2,
    trigger: {
      player: "phaseZhunbeiBegin"
    },
    async cost(event2, trigger2, player2) {
      event2.result = await player2.chooseTarget({
        prompt: get.prompt2(event2.skill),
        filterTarget: lib.filter.all,
        ai(target2) {
          const player3 = get.player();
          if (target2.getHp() > 2) {
            return 0;
          }
          if (target2.getHp() == 2 && player3.countCards("h") < 2) {
            return 0;
          }
          return get.damageEffect(target2, player3, player3, "fire");
        }
      }).forResult();
    },
    async content(event2, trigger2, player2) {
      const {
        targets: [target2]
      } = event2;
      player2.addTempSkill(`${event2.name}_skip`);
      player2.addMark(`${event2.name}_skip`, target2.getHp(), false);
      await target2.damage({ nature: "fire" });
    },
    subSkill: {
      skip: {
        charlotte: true,
        forced: true,
        popup: false,
        onremove: true,
        intro: {
          content: "还需跳过#个阶段"
        },
        trigger: {
          player: "phaseAnyBefore"
        },
        filter(event2, player2) {
          return player2.hasMark("olyanjing_skip");
        },
        async content(event2, trigger2, player2) {
          game.log(player2, "跳过了", `#g${get.translation(trigger2)}`);
          player2.removeMark(event2.name, 1, false);
          if (!player2.hasMark(event2.name)) {
            player2.removeSkill(event2.name);
          }
          trigger2.cancel();
        }
      }
    }
  }

sp:olfenyue.code:
{
    audio: 2,
    zhuanhuanji: true,
    mark: true,
    marktext: "☯",
    intro: {
      content(storage, player2) {
        return `每回合结束时，若本回合有角色受到过属性伤害，你可以${!storage ? "摸两张牌" : "使用一张【杀】"}`;
      }
    },
    trigger: {
      global: "phaseEnd"
    },
    filter(event2, player2) {
      return game.hasGlobalHistory("changeHp", (evt) => {
        return evt.getParent()?.name == "damage" && evt.getParent()?.hasNature();
      });
    },
    direct: true,
    async content(event2, trigger2, player2) {
      const bool = player2.storage[event2.name];
      if (!bool) {
        const result = await player2.chooseBool({
          prompt: get.prompt(event2.name),
          prompt2: get.skillInfoTranslation(event2.name, player2, false),
          choice: true
        }).forResult();
        if (result.bool) {
          player2.logSkill(event2.name);
          player2.changeZhuanhuanji(event2.name);
          await player2.draw({ num: 2 });
        }
      } else {
        await player2.chooseToUse({
          prompt: get.prompt(event2.name),
          prompt2: get.skillInfoTranslation(event2.name, player2, false),
          filterCard(card2, player3) {
            if (get.itemtype(card2) != "card" || get.name(card2) != "sha") {
              return false;
            }
            return lib.filter.filterCard.call(this, card2, player3);
          }
        }).set("onresult", (result) => {
          const player3 = get.player();
          player3.logSkill("olfenyue");
          player3.changeZhuanhuanji("olfenyue");
        });
      }
    }
  }

sp:olbiguo.code:
{
    audio: 2,
    trigger: { player: "phaseDrawEnd" },
    filter(event2, player2) {
      return player2.hasDiscardableCards(player2, "he");
    },
    async cost(event2, trigger2, player2) {
      event2.result = await player2.chooseToDiscard({
        prompt: get.prompt2(event2.skill),
        position: "he",
        ai(card2) {
          return 6 - get.value(card2);
        }
      }).forResult();
    },
    async content(event2, trigger2, player2) {
      const { cards: discard } = event2;
      await player2.modedDiscard({ cards: discard });
      const cards2 = ["basic", "trick", "equip"].map((type) => get.cardPile2((card2) => get.type2(card2) == type));
      if (cards2.length) {
        await player2.showCards(cards2, get.translation(player2) + "发动了【愎果】");
        await player2.gain({ cards: cards2, animate: "gain2" });
      }
      player2.addTempSkill(`${event2.name}_effect`);
    },
    subSkill: {
      effect: {
        audio: "olbiguo",
        charlotte: true,
        trigger: {
          target: "useCardToTargeted"
        },
        filter(event2, player2) {
          return game.hasPlayer((target2) => player2.canCompare(target2));
        },
        async cost(event2, trigger2, player2) {
          event2.result = await player2.chooseTarget({
            prompt: get.prompt(event2.skill),
            prompt2: "可以与一名其他角色拼点，没赢的角色本回合不能使用或打出与双方拼点牌类型相同的牌",
            filterTarget(card2, player3, target2) {
              return player3.canCompare(target2);
            },
            ai(target2) {
              return -get.attitude(_status.event.player, target2) / target2.countCards("h");
            }
          }).forResult();
        },
        async content(event2, trigger2, player2) {
          const {
            targets: [target2]
          } = event2;
          const result = await player2.chooseToCompare(target2).set("small", player2.hasSkill("oldouyu")).forResult();
          const types = [get.type2(result.player), get.type2(result.target)].unique();
          [player2, target2].forEach((target3) => {
            if (target3 != result.winner) {
              target3.addTempSkill("olbiguo_debuff");
              target3.markAuto("olbiguo_debuff", types);
            }
          });
        }
      },
      debuff: {
        charlotte: true,
        onremove: true,
        intro: {
          content: "不能使用或打出$牌"
        },
        mod: {
          cardEnabled(card2, player2) {
            if (player2.getStorage("olbiguo_debuff").includes(get.type2(card2))) {
              return false;
            }
          },
          cardSavable(card2, player2) {
            if (player2.getStorage("olbiguo_debuff").includes(get.type2(card2))) {
              return false;
            }
          },
          cardRespondable(card2, player2) {
            if (player2.getStorage("olbiguo_debuff").includes(get.type2(card2))) {
              return false;
            }
          }
        }
      }
    }
  }

sp:oldouyu.code:
{
    audio: 2,
    trigger: {
      global: "compareCardShowBefore"
    },
    filter(event2, player2) {
      if (event2.player == player2) {
        return true;
      }
      if (event2.targets?.length) {
        return event2.targets.includes(player2);
      } else {
        return event2.target == player2;
      }
    },
    async cost(event2, trigger2, player2) {
      if (trigger2.targets?.length) {
        const targets2 = [trigger2.player, ...trigger2.targets].remove(player2);
        event2.result = await player2.chooseTarget({
          prompt: get.prompt2(event2.skill),
          filterTarget(card2, player3, target2) {
            return get.event().targets.includes(target2);
          },
          ai(target2) {
            return Math.random() - 0.5;
          }
        }).set("targets", targets2).forResult();
      } else {
        const target2 = trigger2.player == player2 ? trigger2.target : trigger2.player;
        event2.result = await player2.chooseBool({
          prompt: get.prompt2(event2.skill, target2),
          choice: true
        }).forResult();
        event2.result.targets = [target2];
      }
    },
    async content(event2, trigger2, player2) {
      const {
        targets: [target2]
      } = event2;
      const targets2 = [player2, target2];
      game.log(targets2, "交换了拼点牌");
      if (trigger2.targets?.length) {
        const { cardlist, lose_list } = trigger2;
        const [card1] = lose_list.find((i) => i[0] === targets2[0])[1];
        const [card2] = lose_list.find((i) => i[0] === targets2[1])[1];
        const index1 = cardlist.indexOf(card1);
        const index2 = cardlist.indexOf(card2);
        if (index1 >= 0 && index2 >= 0) {
          [cardlist[index1], cardlist[index2]] = [cardlist[index2], cardlist[index1]];
        } else {
          trigger2.card1 = index1 < 0 ? card2 : card1;
          cardlist[index1 < 0 ? index2 : index1] = index1 < 0 ? card1 : card2;
        }
      } else {
        const list = [trigger2.card1, trigger2.card2];
        trigger2.card1 = list[1];
        trigger2.card2 = list[0];
      }
      player2.when({ global: ["chooseToCompareAfter", "compareMultipleAfter"] }).filter((evt) => {
        if (evt.name == "chooseToCompare") {
          return evt == trigger2;
        }
        return evt.getParent() == trigger2;
      }).then(async (event3, trigger3, player3) => {
        const winner = trigger3.winner || trigger3.result.winner;
        if (winner == player3) {
          await player3.draw(2);
        }
      });
    }
  }

