sp:olzeguang.code:
{
    audio: 2,
    usable: 1,
    trigger: {
      target: "useCardToTargeted"
    },
    filter(event2, player2) {
      return get.is.damageCard(event2.card) && player2.hasCards("he", (card2) => player2.canRecast(card2));
    },
    async cost(event2, trigger2, player2) {
      event2.result = await player2.chooseCard({
        prompt: get.prompt2(event2.skill),
        position: "he",
        selectCard: Math.min(
          player2.countCards("he", (card2) => player2.canRecast(card2)),
          3
        ),
        filterCard: (card2, player3) => player3.canRecast(card2),
        ai(card2) {
          return 6 - get.value(card2);
        }
      }).forResult();
    },
    async content(event2, trigger2, player2) {
      const { cards: cards2 } = event2;
      await player2.recast(cards2);
      player2.addTempSkill(event2.name + "_give");
      player2.markAuto(event2.name + "_give", [[trigger2, cards2]]);
    },
    subSkill: {
      give: {
        charlotte: true,
        onremove: true,
        trigger: {
          global: "damageSource"
        },
        filter(event2, player2) {
          return player2.getStorage("olzeguang_give").some((arr) => arr[0].card == event2.card && arr[1].someInD("d"));
        },
        forced: true,
        popup: false,
        async content(event2, trigger2, player2) {
          const cards2 = player2.getStorage(event2.name).find((arr) => arr[0].card == trigger2.card)?.[1];
          const toGive = cards2.filterInD("d");
          const result = await player2.chooseTarget({
            createDialog: ["泽光：你可以令一名角色获得这些牌", toGive, [(dialog) => dialog.buttons.forEach((i) => i.style.setProperty("opacity", 1)), "handle"]],
            ai(target2) {
              const { cards: cards3, player: player3 } = get.event();
              return get.attitude(player3, target2) * get.value(cards3, target2);
            }
          }).set("cards", toGive).forResult();
          if (result.bool && result.targets?.length) {
            const {
              targets: [target2]
            } = result;
            player2.line(target2);
            await target2.gain({ cards: toGive, animate: "gain2" });
          }
        }
      }
    }
  }

sp:olchengen.code:
{
    audio: 2,
    trigger: { global: "phaseEnd" },
    filter(event2, player2) {
      const current = _status.currentPhase;
      return current?.countCards("h") <= player2.countCards("h") && game.hasPlayer((target2) => player2.canCompare(target2));
    },
    async cost(event2, trigger2, player2) {
      event2.result = await player2.chooseTarget({
        prompt: get.prompt2(event2.skill),
        filterTarget(card2, player3, target2) {
          return player3.canCompare(target2);
        },
        ai(target2) {
          return -get.attitude(get.player(), target2) / target2.countCards("h");
        }
      }).forResult();
    },
    async content(event2, trigger2, player2) {
      const {
        targets: [target2]
      } = event2;
      const result = await player2.chooseToCompare(target2).forResult();
      if (result.bool) {
        const cards2 = [result.player, result.target];
        while (cards2.length) {
          if (!cards2.some((card2) => get.position(card2) == "d" && (player2.hasUseTarget(card2, void 0, false) || get.info(card2).notarget && lib.filter.cardEnabled(card2, player2)))) {
            break;
          }
          const result2 = await player2.chooseCardButton({
            cards: cards2.filterInD("d"),
            prompt: "承恩：请选择要使用的拼点牌",
            filter(button) {
              const card2 = button.link;
              const player3 = get.player();
              return player3.hasUseTarget(card2, void 0, false) || get.info(card2).notarget && lib.filter.cardEnabled(card2, player3);
            },
            ai(button) {
              return get.player().getUseValue(button.link);
            }
          }).forResult();
          const { links } = result2;
          if (links?.length) {
            cards2.remove(links[0]);
            await player2.chooseUseTarget({ card: links[0], addCount: false });
          } else {
            break;
          }
        }
      } else {
        await target2.chooseToUse({
          prompt: `承恩：是否对${get.translation(player2)}使用一张【杀】`,
          filterCard(card2, player3, event3) {
            if (get.itemtype(card2) !== "card" || get.name(card2) != "sha") {
              return false;
            }
            return lib.filter.filterCard.call(this, card2, player3, event3);
          },
          filterTarget(card2, player3, target3) {
            const { sourcex } = get.event();
            if (target3 != sourcex && !ui.selected.targets.includes(sourcex)) {
              return false;
            }
            return lib.filter.filterTarget.apply(this, arguments);
          },
          complexTarget: true
        }).set("targetRequired", true).set("complexSelect", true).set("sourcex", player2).forResult();
      }
    }
  }

sp:olpingyuan.code:
{
    audio: 2,
    trigger: {
      player: ["enterGame", "phaseBegin"],
      global: "phaseBefore"
    },
    filter(event2, player2, name) {
      if (name == "phaseBegin") {
        return true;
      }
      return event2.name != "phase" || game.phaseNumber == 0;
    },
    async cost(event2, trigger2, player2) {
      if (!player2.getEquip("ol_piliche")) {
        const name = "ol_piliche";
        let card2;
        const target2 = game.findPlayer((current) => {
          const equip = current.getEquip(name);
          return equip?.name === name;
        });
        if (target2) {
          card2 = target2.getEquip(name);
        } else {
          card2 = game.createCard(name, lib.card[name].cardcolor, 9);
        }
        if (!player2.canEquip(card2, true)) {
          return;
        }
        event2.result = await player2.chooseBool({
          prompt: get.prompt(event2.skill),
          prompt2: `将${get.translation(card2)}置于装备区（顶替原装备）并摸一张牌`,
          choice: true
        }).forResult();
        event2.result.cards = [card2];
      } else {
        const choiceList = [`移动霹雳车`, "视为使用一张【杀】"];
        const controls = [];
        const bool1 = player2.canMoveCard(void 0, true, player2, (card2) => get.name(card2) == "ol_piliche");
        const bool2 = player2.hasUseTarget({ name: "sha", isCard: true }, void 0, false);
        if (bool1) {
          controls.push("选项一");
        }
        if (bool2) {
          controls.push("选项二");
        }
        if (!controls.length) {
          return;
        }
        const result = await player2.chooseControl({
          controls: [...controls, "cancel2"],
          choiceList,
          choice: (() => {
            const goon1 = player2.canMoveCard(true, true, player2, (card2) => get.name(card2) == "ol_piliche");
            const goon2 = player2.hasValueTarget({ name: "sha", isCard: true }, void 0, false);
            if (!bool1) {
              return goon2 ? 0 : 2;
            }
            if (!bool2) {
              return goon1 ? 0 : 2;
            }
            return goon2 ? 1 : 2;
          })(),
          prompt: get.prompt(event2.skill),
          prompt2: "移动霹雳车或视为使用一张【杀】"
        }).forResult();
        event2.result = {
          bool: result.control != "cancel2",
          cost_data: {
            index: ["选项一", "选项二"].indexOf(result.control)
          }
        };
      }
    },
    async content(event2, trigger2, player2) {
      const { cards: cards2 } = event2;
      if (cards2?.length) {
        const card2 = cards2[0];
        const owner = get.owner(card2);
        if (owner) {
          owner.$give(card2, player2, false);
        } else {
          player2.$gain2(card2, false);
        }
        await game.delayx();
        await player2.equip(card2);
        await player2.draw();
      } else {
        const { index } = event2.cost_data;
        if (index == 0) {
          await player2.moveCard({ forced: true, sourceTargets: [player2], filter: (card2) => get.name(card2) == "ol_piliche" });
        } else {
          await player2.chooseUseTarget({
            card: get.autoViewAs({ name: "sha", isCard: true }),
            forced: true,
            addCount: false
          });
        }
      }
    }
  }

sp:olliaoyi.code:
{
    audio: 2,
    trigger: {
      global: "useCard"
    },
    filter(event2, player2) {
      const target2 = _status.currentPhase;
