      const list = _status.olzhuangrong_map.get(player2);
      const map = get.info(event2.name).equipMap;
      if (list.length && list.some((name) => player2.canEquip(name))) {
        const name = list.filter((name2) => player2.canEquip(name2)).randomGet();
