          const storage = player2.getStorage("olzhuangrong_destroy");
          return event2.cards?.some((card2) => storage.includes(card2));
        },
        async content(event2, trigger2, player2) {
          const storage = player2.getStorage(event2.name);
          for (const card2 of trigger2.cards) {
            if (storage.includes(card2)) {
              player2.unmarkAuto(event2.name, card2);
              card2._destroy = true;
            }
          }
          if (!storage.length) {
            player2.removeSkill(event2.name);
          }
        }
      },
      count: {
        audio: "olzhuangrong",
