      awake: {
        trigger: {
          player: ["loseAfter"],
          global: ["loseAsyncAfter", "gainAfter", "equipAfter", "addJudgeAfter", "addToExpansionAfter"]
        },
        filter(event2, player2) {
          if (event2.name == "equip" && event2.player == player2) {
            if (event2.getParent().name == "olzhuangrong" && !_status.olzhuangrong_map?.get(player2)?.length) {
              return true;
            }
