      player2.addSkill("olkuangxin_record");
    },
    onremove(player2) {
      player2.removeSkill("olkuangxin_record");
    },
    audio: 2,
    trigger: { player: "phaseUseBegin" },
    forced: true,
    async content(event2, trigger2, player2) {
      const list = [];
      for (let i = 1; i <= player2.hp; i++) {
        list.add(i);
      }
      const result = await player2.chooseControl(list).set("prompt", "###狂信###你失去任意点体力，摸等量的牌并展示已损失体力值+1张手牌。").set("ai", () => {
