          return 0;
        }
        return get.player().hp - 2;
      }).forResult();
      if (!result?.control) {
        return;
      }
      await player2.loseHp(result.control);
      await player2.draw(result.control);
      const num = player2.getDamagedHp() + 1;
      const resultx = await player2.chooseCard(`狂信：展示${num}张手牌`, "h", num, true).set("ai", (card2) => get.player().getUseValue(card2)).forResult();
      if (!resultx?.cards?.length) {
        return;
