      await player2.showCards(resultx.cards, `${get.translation(player2)}发动了【狂信】`);
      player2.setMark(event2.name, resultx.cards.length, false);
    },
    intro: {
      content: "上次展示了#张牌"
    },
    group: ["olkuangxin_recover"],
    subSkill: {
      record: {
        trigger: { player: ["phaseZhunbeiAfter", "phaseBefore", "enterGame"] },
        lastDo: true,
        charlotte: true,
        forced: true,
        popup: false,
        forceDie: true,
        filter(event2, player2) {
          return event2.name != "phase" || game.phaseNumber == 0;
        },
        content() {
          _status.olkuangxin ??= {};
          _status.olkuangxin[player.playerid] = player.hp;
        }
      },
      recover: {
        audio: "olkuangxin",
        trigger: { player: "phaseJieshuBegin" },
        filter(event2, player2) {
          const number = _status.olkuangxin?.[player2.playerid];
          return typeof number === "number" && number !== player2.hp;
