        const evtx = evt.relatedEvent || evt.getParent();
        if (evtx != event2) {
          return false;
        }
        return Object.values(evt.gaintag_map).flat().includes("olleishi");
      });
    },
    async content(event2, trigger2, player2) {
      player2.addTempSkill(event2.name + "_used", ["phaseUseAfter", "phaseChange"]);
      player2.addMark(event2.name + "_used", 1, false);
      const result = await player2.judge().set("callback", () => {
        const player3 = get.event().getParent(2).player, card2 = get.event().judgeResult.card;
        if (get.position(card2, true) == "o") {
          player3.gain(card2, "gain2");
        }
      }).forResult();
      if (result.suit == get.suit(trigger2.card)) {
        const resultx = await player2.chooseTarget(`雷噬：对一名角色造成1点雷电伤害`, true).set("ai", (target3) => get.damageEffect(target3, get.player(), get.player(), "thunder")).forResult();
        if (!resultx?.targets?.length) {
          return;
        }
        const target2 = resultx.targets[0];
        player2.line(target2, "thunder");
        await target2.damage("nocard", "thunder");
      } else {
        const resultx = await player2.chooseCard(`雷噬：展示一张手牌，本回合下次判定时，若此牌在你的手牌区内，将此牌作为判定牌。`, "h", true).set("ai", (card2) => 6 - get.value(card2)).forResult();
        if (!resultx?.cards?.length) {
          return;
        }
        const skill = event2.name + "_judge";
        player2.addGaintag(resultx.cards, skill);
        player2.addTempSkill(skill);
        await player2.showCards(resultx.cards, `${get.translation(player2)}发动【雷噬】展示的牌`);
      }
    },
    group: ["olleishi_mark"],
    ai: {
      combo: "olkuangxin"
    },
    subSkill: {
      judge: {
        audio: "olleishi",
        onremove(player2, skill) {
          player2.removeGaintag(skill);
        },
        trigger: {
          player: "judgeBefore"
        },
        forced: true,
        popup: false,
        charlotte: true,
        filter(event2, player2) {
          return !event2.directresult && player2.countCards("h", (card2) => card2.hasGaintag("olleishi_judge"));
        },
        async content(event2, trigger2, player2) {
          const cards2 = player2.getCards("h", (card2) => card2.hasGaintag(event2.name));
          if (!cards2.length) {
            return;
          }
          let result;
          if (cards2.length == 1) {
            result = { cards: cards2 };
          } else {
            result = await player2.chooseCard(`雷噬：请选择一张牌作为判定牌`, "h", true, (card2, player3) => {
              return card2.hasGaintag(get.event().getParent().name);
            }).set("ai", (card2) => -get.value(card2)).forResult();
          }
          if (!result?.cards?.length) {
            return;
          }
          player2.$throw(result.cards);
          trigger2.directresult = result.cards[0];
        }
      },
      used: {
        charlotte: true,
        onremove: true
      },
      mark: {
        trigger: {
          global: "showCardsEnd"
        },
        forced: true,
        charlotte: true,
        popup: false,
        firstDo: true,
        filter(event2, player2) {
          return event2.cards.some((i) => get.owner(i) == player2);
        },
        content() {
          game.broadcastAll(
            function(cards2) {
              cards2.forEach((card2) => card2.addGaintag("olleishi"));
            },
            trigger.cards.filter((i) => get.owner(i) == player)
          );
          player.when({ global: "phaseAfter" }).step(async () => {
            player.removeGaintag("olleishi");
          });
        }
      }
    }
  }

