sp:olyouque.code:
{
    audio: 2,
    enable: "phaseUse",
    filter(event2, player2) {
      return player2.getExpansions("olxiewei").length && game.hasPlayer((target2) => player2.canCompare(target2));
    },
    delay: false,
    lose: false,
    discard: false,
    async precontent(event2, trigger2, player2) {
      const cards2 = player2.getExpansions("olxiewei");
      const result = await player2.chooseButtonTarget({
        createDialog: [`###诱阙###${get.skillInfoTranslation("olyouque", null, false)}`, cards2],
        cards: cards2,
        filterButton(button) {
          return !get.event().cards.some((card2) => get.number(card2) < get.number(button.link));
        },
        filterTarget(card2, player3, target2) {
          return player3.canCompare(target2, true);
        },
        ai2(target2) {
          return -get.attitude(get.player(), target2) * target2.countCards("h");
        }
      }).forResult();
      if (result?.bool && result.links?.length && result.targets?.length) {
        event2.result.targets = result.targets;
        event2.result.cards = result.links;
      } else {
        event2.getParent().goto(0);
        if (player2 != game.me && !player2.isOnline()) {
          event2.getParent()._aiexclude.add("olyouque");
        }
      }
    },
    async content(event2, trigger2, player2) {
      const card2 = event2.cards[0], target2 = event2.targets[0];
      if (!player2.canCompare(target2, true)) {
        return;
      }
      player2.addTempSkill(event2.name + "_effect");
      let next = player2.chooseToCompare(target2);
      if (!next.fixedResult) {
        next.fixedResult = {};
      }
      next.fixedResult[player2.playerid] = card2;
      const resultx = await next.forResult();
      for (const targetx of [player2, target2]) {
        if (resultx.winner != targetx) {
          const card3 = targetx == player2 ? resultx.player : resultx.target, num = get.number(card3), winner = resultx.winner;
          await targetx.modedDiscard(targetx.getCards("h", (cardx) => get.number(cardx, player2) > num));
          if (winner && targetx.canUse({ name: "sha", isCard: true }, winner, false, false)) {
            const sha = get.autoViewAs({ name: "sha", isCard: true, storage: { olyouque: true } });
            await targetx.useCard(sha, winner, false);
          }
        }
      }
    },
    ai: {
      combo: "olxiewei",
      order: 7,
      result: {
        player: 1
      }
    },
    subSkill: {
      effect: {
        audio: "olyouque",
        trigger: { global: "damageSource" },
        filter(event2, player2) {
          return event2.card?.storage?.olyouque;
        },
        forced: true,
        async content(event2, trigger2, player2) {
          await player2.draw(2);
          if (!player2.getExpansions("olxiewei").some((card2) => get.suit(card2) == "spade")) {
            player2.tempBanSkill("olyouque", ["phaseChange", "phaseUseAfter"]);
          }
        }
      }
    }
  }

