sp:oljiyun.code:
{
    audio: 2,
    trigger: {
      player: "phaseZhunbeiBegin",
      global: "useCardAfter"
    },
    filter(event2, player2) {
      if (event2.name == "phaseZhunbei") {
        return true;
      }
      return event2.player.hasHistory("lose", (evt) => {
        const evtx = evt.relatedEvent || evt.getParent();
        if (evtx != event2) {
          return false;
        }
        return Object.values(evt.gaintag_map).flat().includes("oljiyun_effect");
      }) && player2.getExpansions("oljiyun")?.length < 3;
    },
    async cost(event2, trigger2, player2) {
      if (trigger2.name == "phaseZhunbei") {
        const max = Math.max(1, player2.getExpansions(event2.skill).length);
        event2.result = await player2.chooseTarget(`###${get.prompt(event2.skill)}###令至多${get.cnNumber(max)}名角色各摸一张牌`, [1, max]).set("ai", (target2) => {
          const player3 = get.player();
          return get.effect(target2, { name: "draw" }, player3, player3);
        }).forResult();
      } else {
        let cards2 = [];
        trigger2.player.checkHistory("lose", (evt) => {
          if ((evt.relatedEvent || evt.getParent()) != trigger2) {
            return false;
          }
          cards2.addArray(evt.cards.filter((card2) => evt.gaintag_map[card2.cardid]?.includes("oljiyun_effect") && ["e", "o", "d"].includes(get.position(card2))));
        });
        if (cards2.length > 3 - player2.getExpansions(event2.skill).length) {
          const num = 3 - player2.getExpansions(event2.skill).length;
          const result = await player2.chooseCardButton(`集运：请将${num}张牌作为「粮」置于武将牌上`, cards2, num, true).set("ai", (button) => {
            return get.buttonValue(button);
          }).forResult();
          cards2 = result.links;
        }
        if (!cards2.length) {
          return;
        } else {
          event2.result = {
            bool: true,
            cost_data: cards2
          };
        }
      }
    },
    async content(event2, trigger2, player2) {
      if (trigger2.name == "phaseZhunbei") {
        const targets2 = event2.targets?.sortBySeat();
        for (const target2 of targets2) {
          await target2.draw("nodelay").set("gaintag", ["oljiyun_effect"]);
        }
        await game.delayx();
      } else {
        const cards2 = event2.cost_data;
        await player2.addToExpansion(cards2, "gain2").set("gaintag", ["oljiyun"]);
      }
    },
    marktext: "粮",
    intro: {
      name: "粮（集运）",
      markcount: "expansion",
      content: "expansion"
    },
    onremove: true,
    group: ["oljiyun_init"],
    subSkill: {
      init: {
        audio: "oljiyun",
        trigger: {
          player: "enterGame",
          global: "phaseBefore"
        },
        filter(event2, player2) {
          return event2.name != "phase" || game.phaseNumber == 0;
        },
        forced: true,
        content() {
          const cards2 = [];
          for (const type of ["basic", "trick", "equip"]) {
            const card2 = get.cardPile2((cardx) => get.type2(cardx) == type && !cards2.includes(cardx));
            if (card2) {
              cards2.push(card2);
            }
          }
          if (cards2.length) {
            player.addToExpansion(cards2, "gain2").gaintag.add("oljiyun");
          }
        }
      }
    }
  }

