    enable: ["chooseToUse", "chooseToRespond"],
    hiddenCard(player2, name) {
      if (player2.getExpansions("oljiyun").some((card2) => card2.name == name)) {
        return true;
      }
    },
    filter(event2, player2) {
      if (event2.responded || event2.olshuliang) {
        return false;
      }
      return player2.getExpansions("oljiyun").some((card2) => event2.filterCard(card2, player2, event2));
    },
    usable: 1,
    chooseButton: {
      dialog(event2, player2) {
        return ui.create.dialog("输粮", player2.getExpansions("oljiyun"), "hidden");
      },
      filter(button, player2) {
        const evt = _status.event.getParent();
        return evt.filterCard(button.link, player2, evt);
      },
      check(button) {
        const card2 = button.link, player2 = get.player();
        if (get.event().getParent().type != "phase") {
          return 1;
        }
        return player2.getUseValue(card2);
      },
      backup(links, player2) {
        return {
          audio: "olshuliang",
          filterCard(card2) {
            return card2 === lib.skill.olshuliang_backup.card;
          },
          selectCard: -1,
          viewAs: links[0],
          card: links[0],
          position: "x"
        };
      },
      prompt(links, player2) {
        return "输粮：请选择" + get.translation(links[0]) + "的目标";
      }
    },
    ai: {
      combo: "oljiyun",
      effect: {
        target(card2, player2, target2, effect) {
          if (get.tag(card2, "respondShan")) {
            return 0.7;
          }
          if (get.tag(card2, "respondSha")) {
            return 0.7;
          }
        }
      },
      order: 9,
      respondShan: true,
      respondSha: true,
      result: {
        player(player2) {
          if (_status.event.dying) {
            return get.attitude(player2, _status.event.dying);
          }
          return 1;
        }
      }
    },
    group: ["olshuliang_allocate"],
    subSkill: {
      backup: { audio: "olshuliang" },
      allocate: {
        audio: "olshuliang",
        trigger: { player: "phaseJieshuBegin" },
        filter(event2, player2) {
          return player2.getExpansions("oljiyun").length > 0;
        },
        async cost(event2, trigger2, player2) {
          const cards2 = player2.getExpansions("oljiyun");
          event2.result = await player2.chooseBool().set("createDialog", [`###${get.prompt(event2.skill)}###将任意张「集运」牌分配给至多等量角色`, cards2]).set("ai", () => {
            return true;
          }).forResult();
        },
        async content(event2, trigger2, player2) {
          if (_status.connectMode) {
            game.broadcastAll(() => _status.noclearcountdown = true);
          }
          const cards2 = player2.getExpansions("oljiyun"), map = {};
          while (cards2.length) {
            const result = await player2.chooseButtonTarget({
              createDialog: [`集运：请选择要分配的牌和目标`, cards2],
              forced: Object.keys(map).length == 0,
              selectButton: [1, cards2.length],
              cardsx: cards2,
              map,
              filterTarget: true,
              ai1(button) {
                if (get.event().cardsx.length < 2) {
                  return false;
                }
                const { player: player3, map: map2 } = get.event();
                return Math.max(
                  ...game.filterPlayer().map((target2) => {
                    return [...ui.selected.cards, button.link, ...map2[target2.playerid] || []].reduce((sum, card2) => {
                      return get.value(card2, target2) * get.attitude(player3, target2);
                    }, 0);
                  })
                );
              },
              ai2(target2) {
                const player3 = get.player();
                const card2 = ui.selected.buttons[0].link;
                if (card2) {
                  return get.value(card2, target2) * get.attitude(player3, target2);
                }
                return 0;
              }
            }).forResult();
            if (result?.bool && result.targets?.length && result.links?.length) {
              cards2.removeArray(result.links);
              const id = result.targets[0].playerid;
              if (!map[id]) {
                map[id] = [];
              }
              map[id].addArray(result.links);
            } else {
              break;
            }
          }
          if (_status.connectMode) {
            game.broadcastAll(() => {
              delete _status.noclearcountdown;
              game.stopCountChoose();
            });
          }
          if (Object.keys(map).length) {
            const gain_list = [];
            for (const i in map) {
              const source = (_status.connectMode ? lib.playerOL : game.playerMap)[i];
              player2.line(source, "green");
              gain_list.push([source, map[i]]);
              game.log(source, "获得了", map[i]);
            }
            await game.loseAsync({
              gain_list,
              giver: player2,
              animate: "gain2"
            }).setContent("gaincardMultiple");
          }
        }
      }
    }
  }

