sp:olfeibian.code:
{
    audio: 2,
    trigger: { global: "useCardAfter" },
    filter(event2, player2) {
      if (event2.player === player2) {
        return _status.currentPhase === player2;
      }
      return event2.targets?.includes(player2);
    },
    forced: true,
    logTarget: "player",
    async content(event2, trigger2, player2) {
      const target2 = trigger2.player;
      const cards2 = target2.getDiscardableCards(target2, "h");
      if (cards2.length) {
        await target2.discard(cards2.randomGets(1));
      }
      const info = target2.forceCountChoose;
      if (_status.countDown) {
        return;
      }
      let time;
      if (typeof info?.["chooseToUse"] === "number") {
        time = info["chooseToUse"];
      } else if (typeof info?.default === "number") {
        time = info.default;
      } else {
        if (!_status.connectMode) {
          return;
        }
        time = lib.configOL.choose_timeout;
      }
      if (time) {
        time = parseInt(time);
        if (time > 1) {
          time--;
          target2.addTempSkill("olfeibian_time", "roundStart");
          target2.addMark("olfeibian_time", 1, false);
          game.broadcastAll(
            (player3, time2) => {
              if (!player3.forceCountChoose) {
                player3.forceCountChoose = {};
              }
              player3.forceCountChoose.chooseToUse = time2;
            },
            target2,
            time
          );
          game.log(target2, "出牌时限", "#y-1s");
        }
      }
    },
    group: ["olfeibian_init", "olfeibian_loseHp"],
    init() {
      game.broadcastAll(() => {
        const countDown = game.countDown;
        if (typeof countDown !== "function") {
          return;
        }
        game.countDown = function(time, onEnd) {
          const newOnEnd = () => {
            const event2 = get.event();
            if (event2?.name === "chooseToUse" && event2.player?.isIn()) {
              event2.player.addTempSkill("olfeibian_effect");
            }
            if (typeof onEnd === "function") {
              onEnd();
            }
          };
          return countDown.call(this, time, newOnEnd);
        };
      });
    },
    subSkill: {
      effect: { charlotte: true },
      time: {
        charlotte: true,
        onremove(player2, skill) {
          game.broadcastAll(
            (player3, time) => {
              player3.forceCountChoose.chooseToUse = time;
            },
            player2,
            player2.forceCountChoose.chooseToUse + player2.countMark(skill)
          );
          delete player2.storage[skill];
        }
      },
      init: {
        audio: "olfeibian",
        trigger: { global: "phaseBefore", player: "enterGame" },
        filter: (event2) => event2.name !== "phase" || game.phaseNumber === 0,
        forced: true,
        content() {
          game.broadcastAll((player2) => {
            if (!player2.forceCountChoose) {
              player2.forceCountChoose = {};
            }
            player2.forceCountChoose.chooseToUse = 15;
          }, player);
          game.log(player, "的出牌时限改为了", "#g15s");
        }
      },
      loseHp: {
        audio: "olfeibian",
        trigger: { global: "phaseEnd" },
        filter(event2, player2) {
          return game.hasPlayer((target2) => target2.hasSkill("olfeibian_effect"));
        },
        logTarget(event2, player2) {
          return game.filterPlayer((target2) => target2.hasSkill("olfeibian_effect"));
        },
        forced: true,
        content() {
          for (const i of event.targets) {
            i.loseHp();
          }
        }
      }
    }
  }

