      player2.markAuto("olfulve_used", [choice]);
      await map[choice](player2, target2, trigger2.getParent());
      choice = choice == "damage" ? "gain" : "damage";
      const sourcex = player2;
      target2.when({ global: "useCardAfter" }).filter((evt) => {
        return evt === trigger2.getParent();
      }).step(async (event3, trigger3, player3) => {
