          },
          "复掠：是否对" + get.translation(sourcex) + "使用一张【杀】"
        ).set("targetRequired", true).set("complexSelect", true).set("complexTarget", true).set("filterTarget", function(card2, player4, target3) {
          if (target3 != get.event().sourcex && !ui.selected.targets.includes(get.event().sourcex)) {
            return false;
          }
          return lib.filter.filterTarget.apply(this, arguments);
        }).set("sourcex", sourcex).set("func", map[choice]).set("oncard", (card2, player4) => {
