      await target2.recover();
      await target2.link(false);
      const targets2 = [target2.getPrevious(), target2.getNext()].unique();
      if (targets2.length) {
        const func = async (target3) => {
          if (target3?.isIn()) {
            await target3.link(true);
          }
        };
        await game.doAsyncInOrder(targets2, func);
      }
      target2.addSkill("oldici_effect");
      target2.markAuto("oldici_effect", [player2]);
    },
    ai: {
      order: 7,
      result: {
        player(player2, target2) {
          const targets2 = [target2.getPrevious(), target2.getNext()].filter((current) => current?.isIn() && !current.isLinked()).unique();
          let num = target2.isLinked() ? get.effect(target2, { name: "tiesuo" }, player2, player2) : 0;
          if (targets2.length) {
            for (const current of targets2) {
              num += get.effect(current, { name: "tiesuo" }, player2, player2);
              const goon = current.getStorage("oldici_effect").includes(player2);
              const max = Math.max(...[get.damageEffect(current, player2, player2, "thunder"), get.effect(current, { name: "shunshou_copy", position: "h" }, player2, player2)].concat(goon ? [] : [0]));
              num += max * (goon ? 1 : 0.2);
            }
          }
          return num + get.effect(target2, { name: "shunshou_copy", position: "h" }, player2, player2) + get.recoverEffect(target2, player2, player2);
        }
      }
    },
    subSkill: {
