sp:spoljinglei.code:
{
    audio: 2,
    trigger: { global: "useCardAfter" },
    usable: 1,
    filter(event2, player2) {
      return event2.card.name === "jiu" && !game.hasPlayer((current) => current.isDying());
    },
    check(event2, player2) {
      if (get.damageEffect(player2, player2, player2, "thunder") > 0) {
        return true;
      }
      return Math.max(
        ...[0].concat(
          game.filterPlayer((target2) => {
            return target2.hasSkill("spolzhujiu", null, null, false);
          }).map((target2) => {
            return get.info("spoljinglei").getEffect(player2, target2);
          })
        )
      ) > 0;
    },
    async content(event2, trigger2, player2) {
      await player2.damage("thunder", "nosource");
      if (!player2.isIn() || !game.hasPlayer((target3) => target3.hasSkill("spolzhujiu", null, null, false))) {
        return;
      }
      const result = await player2.chooseTarget(
        "惊雷：请选择一名拥有〖煮酒〗的角色",
        (card2, player3, target3) => {
          return target3.hasSkill("spolzhujiu", null, null, false);
        },
        true
      ).set("prompt2", "令其将手牌调整至体力上限（至多摸至5），然后若该角色不为你：其须将以此法弃置的牌交给你").set("ai", (target3) => get.info("spoljinglei").getEffect(get.player(), target3)).forResult();
      const target2 = result.targets?.[0];
      if (!target2) {
        return;
      }
      const num = target2.maxHp - target2.countCards("h");
      if (num === 0) {
        return;
      }
      if (num > 0) {
        await target2.drawTo(Math.min(target2.maxHp, 5));
      } else {
        const num2 = Math.min(
          target2.countCards("h") - target2.maxHp,
          target2.countCards("h", (card2) => lib.filter.cardDiscardable(card2, target2))
        );
        if (num2 === 0) {
          return;
        }
        const result2 = await target2.chooseToDiscard(num2, true, "allowChooseAll").forResult();
        if (player2 != target2 && result2?.cards?.someInD("d")) {
          await player2.gain(result2.cards.filterInD("d"), "gain2").set("giver", target2);
        }
      }
    },
    getEffect(player2, target2) {
      if (player2.countCards("hs", (card2) => player2.canSaveCard(card2, player2)) < 2 - player2.hp) {
        return 0;
      }
      const draw = Math.min(5, target2.maxHp) - target2.countCards("h");
      const eff1 = get.damageEffect(player2, player2, player2, "thunder");
      if (draw > 0) {
        return get.effect(target2, { name: "draw" }, player2, player2) * draw + eff1;
      }
      if (draw < -1) {
        return get.effect(target2, { name: "guohe_copy", position: "h" }, player2, player2) * Math.sqrt(Math.min(target2.countDiscardableCards(target2, "h"), -draw)) + eff1;
      }
      return 0;
    },
    ai: { combo: "spolzhujiu" }
  }

