    trigger: { player: "damageEnd" },
    filter(event2, player2) {
      const cardPile = Array.from(ui.cardPile.childNodes).reverse();
      return cardPile[0] && get.color(cardPile[0]) === "red";
    },
    frequent: true,
    /*
    async cost(event, trigger, player) {
    	const cardPile = Array.from(ui.cardPile.childNodes).reverse();
    	const redCards = [];
    	for (const card of cardPile) {
    		if (get.color(card) == "red") {
    			redCards.push(card);
    			if (redCards.length >= 3) break;
    		} else break;
    	}
    	const result = await player
    		.chooseNumbers(get.prompt2("olsiqi"), [{ prompt: "请选择你要亮出的牌数", min: 1, max: redCards.length }])
    		.set("processAI", () => {
    			return [get.event().maxNum];
    		})
    		.set("maxNum", redCards.length)
    		.forResult();
    	if (result.bool) {
    		const number = result.numbers[0];
    		event.result = {
    			bool: result.bool,
    			cost_data: number,
    		};
    	}
    },
    */
    async content(event2, trigger2, player2) {
      let cards2 = [];
      const cardPile = Array.from(ui.cardPile.childNodes).reverse();
      for (const card2 of cardPile) {
        if (get.color(card2) == "red") {
          cards2.push(card2);
          if (cards2.length >= 3) {
            break;
          }
        } else {
          break;
        }
      }
      if (!cards2.length) {
        return;
      }
      const next = game.cardsGotoOrdering(cards2);
      await next;
      cards2 = next.cards.slice();
      if (!cards2.length) {
        return;
      }
      await player2.showCards(cards2, get.translation(player2) + "发动了【思泣】");
      while (cards2.length) {
        if (cards2.every((card2) => {
          if (!lib.filter.cardEnabled(card2, player2)) {
            return true;
          }
          const name = ["tao", "wuzhong"];
          if (name.includes(card2.name) || get.type(card2) == "equip") {
            return !game.hasPlayer((target2) => lib.filter.targetEnabled2(card2, player2, target2));
          }
          return true;
        })) {
          break;
        }
        const result2 = await player2.chooseCardButton({
          cards: cards2,
          prompt: "思泣：请选择要使用的牌",
          filter(button) {
            const card2 = button.link;
            if (!lib.filter.cardEnabled(card2, get.player())) {
              return false;
            }
            if (["tao", "wuzhong"].includes(card2.name) || get.type(card2) == "equip") {
              return game.hasPlayer((target2) => lib.filter.targetEnabled2(card2, get.player(), target2));
            }
            return false;
          },
          ai(button) {
            return get.player().getUseValue(button.link);
          }
        }).forResult();
        if (result2.bool) {
          const card2 = result2.links[0];
          game.broadcastAll((card3) => {
            lib.skill.olsiqi_backup.viewAs = card3;
