        }
      }
    }
  }

sp:olqingshu.code:
{
    audio: 3,
    trigger: {
      global: "phaseBefore",
      player: ["enterGame", "phaseZhunbeiBegin", "phaseJieshuBegin"]
    },
    filter(event2, player2) {
      return event2.name !== "phase" || game.phaseNumber === 0;
    },
    forced: true,
    async content(event2, trigger2, player2) {
      let { tianshuTrigger: fromItems, tianshuContent: toItems } = get.info("olhedao");
      fromItems = fromItems.randomGets(3);
      const froms = await player2.chooseButton(
        [
          '###青书：请选择“天书”时机###<div class="text center">时机触发等级将决定后续效果词条的等级</div>',
          [
            (dialog) => {
              const { fromItems: fromItems2 } = get.event();
              dialog.css({ top: get.is.phoneLayout() ? "20%" : "25%" });
              dialog.addNewRow(
                ...fromItems2.map((item, index) => {
                  return {
                    item: [`${item.name}<br>（触发等级：${item.fromIndex}）`],
                    custom(itemContainer) {
                      itemContainer.link = index;
                      itemContainer.classList.add("button");
                      dialog.buttons.add(itemContainer);
                    },
                    clickItemContainer(itemContainer, 棍, 母, e) {
                      ui.click.button.call(itemContainer, e);
                    }
                  };
                })
              );
            },
            "handle"
          ]
        ],
        true
      ).set("fromItems", fromItems).set("ai", () => 1 + Math.random()).forResult();
      if (!froms?.links?.length) {
        return;
      }
      const from = fromItems[froms.links[0]];
      const items = toItems.filter((item) => !item.filter || item.filter(from.name));
      toItems = items.filter((item) => from.fromIndex === item.toIndex).randomGets(3);
      if (get.isLuckyStar(player2) || Math.random() > 0.5) {
        let levelItem = items.filter((item) => from.fromIndex + 1 === item.toIndex).randomGet();
        if (levelItem) {
          toItems[get.rand(0, toItems.length - 1)] = levelItem;
        }
      }
      const tos = await player2.chooseButton(
        [
          '###青书：请选择“天书”效果###<div class="text center">' + from.name + "</div>",
          [
            (dialog) => {
              const { toItems: toItems2, from: from2 } = get.event();
              dialog.css({ top: get.is.phoneLayout() ? "20%" : "25%" });
              dialog.addNewRow(
                ...toItems2.map((item, index) => {
                  return {
                    item: [`${["", '<span style="color: #EEC900; text-shadow: 0.5px 0.5px 0.5px white, 0.5px 0.5px 0.5px white, 0.5px 0.5px 0.5px white, 0.5px 0.5px 0.5px white;">'][item.toIndex - from2.fromIndex]}${item.name}${["", "</span>"][item.toIndex - from2.fromIndex]}`],
                    custom(itemContainer) {
                      itemContainer.link = index;
                      itemContainer.classList.add("button");
                      dialog.buttons.add(itemContainer);
                    },
                    clickItemContainer(itemContainer, 棍, 母, e) {
                      ui.click.button.call(itemContainer, e);
                    }
                  };
                })
              );
            },
            "handle"
          ]
        ],
        true
      ).set("toItems", toItems).set("from", from).set("ai", () => 1 + Math.random()).forResult();
      if (!tos?.links?.length) {
        return;
      }
      const to = toItems[tos.links[0]];
      let skill;
      while (true) {
        skill = "olhedao_tianshu_" + Math.random().toString(36).slice(-8);
        if (!lib.skill[skill]) {
          break;
        }
      }
      game.broadcastAll(
        (skill2, from2, to2) => {
          const { filter: filterFrom, ...otherFrom } = from2.effect;
          const { filter: filterTo, ...otherTo } = to2.effect;
          lib.skill[skill2] = {
            nopop: true,
            olhedao: true,
            charlotte: true,
            init(player3, skill3) {
              player3.storage[skill3] ??= [0, []];
            },
            onremove: true,
            filter(...args) {
              return (filterFrom ? filterFrom(...args) : true) && (filterTo ? filterTo(...args) : true);
            },
            markimage: "image/card/tianshu2.png",
            intro: {
              markcount: (storage = [0]) => storage[0],
              content(storage = [0, []], player3, book) {
                const [count, targets2] = storage;
                if (!book) {
                  return "查无此书";
                }
                return [
                  `此书还可使用${count}次`,
                  (() => {
                    if (!get.info(book)?.nopop || [player3, ...targets2].some((i) => i.isUnderControl(true) || i.isFriendOf(game.me))) {
                      return lib.translate[`${book}_info`];
                    }
                    return "此书仍是个秘密";
                  })()
                ].map((str) => `<li>${str}`).join("<br>");
              }
            },
            ...otherFrom,
            ...otherTo
          };
          lib.translate[skill2] = "天书";
          lib.translate[`${skill2}_info`] = `${from2.name}，${to2.name}。`;
          game.finishSkill(skill2);
        },
        skill,
        from,
        to
      );
      player2.addSkill(skill);
      lib.skill.olhedao.tianshuClear(skill, player2, -2);
      const skills2 = player2.getSkills(null, false, false).filter((skill2) => get.info(skill2)?.olhedao);
      const num = skills2.length - lib.skill.olhedao.getLimit(player2);
      if (num > 0) {
        const result = num < skills2.length ? await player2.chooseButton(
          [
            "青书：选择失去" + get.cnNumber(num) + "册多余的“天书”",
            [
              (dialog) => {
                const { player: player3, skills: skills3 } = get.event();
                dialog.css({ top: get.is.phoneLayout() ? "20%" : "25%" });
                dialog.addNewRow(
                  ...skills3.map((item) => {
                    return {
                      item: [`${lib.translate[`${item}_info`]}<br>（剩余${player3.storage[item][0]}次）`],
                      custom(itemContainer) {
                        itemContainer.link = item;
                        itemContainer.classList.add("button");
                        dialog.buttons.add(itemContainer);
                      },
                      clickItemContainer(itemContainer, 棍, 母, e) {
                        ui.click.button.call(itemContainer, e);
                      }
                    };
                  })
                );
              },
              "handle"
            ]
          ],
          true,
          num
        ).set("skills", skills2).set("ai", () => 1 + Math.random()).forResult() : { bool: true, links: skills2 };
        if (result?.bool && result.links?.length) {
          player2.removeSkill(result.links);
        }
      }
    },
    ai: { threaten: 4 }
  }

