        return false;
      }
      return game.hasPlayer((current) => get.info("spolzhubei").filterTarget(null, player2, current));
    },
    filterTarget(card2, player2, target2) {
      return player2 != target2;
    },
    prompt(event2, player2) {
      if (event2.spolzhubei_num) {
        return `出牌阶段各限一次，你可以令一名其他角色将至少${get.cnNumber(event2.spolzhubei_num)}张牌当作无距离和任何次数限制的【杀】或【决斗】对你使用。`;
      }
      return "出牌阶段各限一次，你可以令一名其他角色将至少X张牌当作无距离和任何次数限制的【杀】或【决斗】对你使用（X为本回合所有角色本回合使用基本牌的次数+1）。";
    },
    async content(event2, trigger2, player2) {
      const { target: target2 } = event2, num = event2.getParent(2).spolzhubei_num;
      const list = get.inpileVCardList((info) => {
        if (!["sha", "juedou"].includes(info[2]) || info[3]) {
          return false;
        }
        return !player2.getStorage("spolzhubei_used").includes(info[2]);
      });
      if (!list.length) {
        return;
      }
      const links = list.length == 1 ? list : (await target2.chooseButton([`请选择要对${get.translation(player2)}使用的牌`, [list, "vcard"]], true).set("ai", (button) => {
        const player3 = get.player(), target3 = get.event().getParent().player, { link } = button;
        return get.effect(target3, { name: link[2] }, player3, player3);
      }).forResult()).links;
      if (!links?.length) {
        return;
      }
      const viewAs = { name: links[0][2] };
      player2.addTempSkill("spolzhubei_used", "phaseUseAfter");
      player2.markAuto("spolzhubei_used", [viewAs.name]);
      const count = target2.countCards("hes", (cardx) => target2.canUse(get.autoViewAs({ name: viewAs.name }, [cardx]), player2, false));
      if (count >= num) {
        game.broadcastAll(
          (viewAs2, num2) => {
            lib.skill.spolzhubei_backup.viewAs = viewAs2;
            lib.skill.spolzhubei_backup.selectCard = [num2, Infinity];
          },
          viewAs,
          num
        );
        const next = target2.chooseToUse();
        next.set("openskilldialog", `逐北：将至少${get.cnNumber(num)}张牌当作${get.translation(viewAs.name)}对${get.translation(player2)}使用`);
        next.set("norestore", true);
        next.set("_backupevent", "spolzhubei_backup");
        next.set("custom", {
          add: {},
          replace: { window() {
          } }
        });
        next.backup("spolzhubei_backup");
        next.set("targetRequired", true);
        next.set("complexSelect", true);
        next.set("complexTarget", true);
        next.set("filterTarget", function(card2, player3, target3) {
          if (target3 != _status.event.sourcex && !ui.selected.targets.includes(_status.event.sourcex)) {
            return false;
          }
          return lib.filter.targetEnabled.apply(this, arguments);
        });
        next.set("sourcex", player2);
        next.set("addCount", false);
        next.set("forced", true);
        player2.when({ player: "damageEnd" }).filter((evt) => evt.getParent(4) == event2 && evt.cards.someInD()).step(async (event3, trigger3, player3) => {
          await player3.gain(trigger3.cards.filterInD(), "gain2");
        });
        player2.when({ global: "useCardAfter" }).filter((evt) => evt.getParent(2) == event2 && !player2.hasHistory("damage", (evtx) => evtx.card == evt.card) && (player2.isDamaged() || evt.player.isIn() && [player2, evt.player].some((current) => current.countCards("h")))).step(async () => {
          await player2.recover();
          if (target2.isIn() && [player2, target2].some((current) => current.countCards("h"))) {
            const { bool } = await player2.chooseBool(`逐北`, `与${get.translation(target2)}交换手牌？`).set("choice", get.attitude(player2, target2) > 0 || player2.countCards("h") < target2.countCards("h")).forResult();
            if (bool) {
              await player2.swapHandcards(target2);
            }
          }
        });
        await next;
      } else {
        await player2.recover();
        if (target2.isIn() && [player2, target2].some((current) => current.countCards("h"))) {
          const { bool } = await player2.chooseBool(`逐北`, `与${get.translation(target2)}交换手牌？`).set("choice", get.attitude(player2, target2) > 0 || player2.countCards("h") < target2.countCards("h")).forResult();
          if (bool) {
            await player2.swapHandcards(target2);
          }
        }
      }
    },
    ai: {
      order: 2,
      result: {
        player(player2, target2, cardx) {
          return 1 + Math.max.apply(
            Math,
            ["sha", "juedou"].filter((name) => !player2.getStorage("spolzhubei_used").includes(name) && target2.canUse(get.autoViewAs({ name }, [cardx]), player2, false)).map((name) => get.effect(player2, { name }, target2, player2))
          );
        }
      }
    },
    subSkill: {
      used: {
        charlotte: true,
        onremove: true
      },
