          return get.itemtype(card2) == "card";
        },
        position: "hes",
        ai1(card2) {
          if (ui.selected.cards.length) {
            return 0;
          }
          return 5 - get.value(card2);
        },
        log: false,
        allowChooseAll: true
      }
    }
  }

