    },
    locked: true,
    async cost(event2, trigger2, player2) {
      if (trigger2.name === "damage") {
        const target2 = trigger2.player;
        const dialog = ['###凤瑶###<div class="text center">弃置你或' + get.translation(target2) + "场上的一张黑桃牌，令此伤害+1</div>"];
        for (const current of [player2, target2]) {
          for (const pos of ["e", "j"]) {
            const cards2 = current.getCards(pos, (card2) => get.suit(card2) === "spade" && lib.filter.cardDiscardable(card2, player2));
            if (cards2.length) {
              dialog.push('<div class="text center">' + (current === player2 ? "你" : get.translation(current)) + "的" + { e: "装备区", j: "判定区" }[pos] + "</div>");
              dialog.push(cards2);
            }
          }
        }
        event2.result = await player2.chooseButton(dialog, true).set("ai", (button) => {
          const player3 = get.player(), card2 = button.link, owner = get.owner(card2);
          return -get.attitude(player3, owner) * get.value(card2, owner);
        }).forResult();
        event2.result.cards = event2.result.links;
        event2.result.targets = [target2];
      } else {
        event2.result = { bool: true };
      }
    },
    async content(event2, trigger2, player2) {
      if (trigger2.name === "damage") {
        const owner = get.owner(event2.cards[0]);
        await owner.modedDiscard(event2.cards);
        trigger2.num++;
      } else {
        let num = 0;
        game.countPlayer2((current) => {
          const cards2 = trigger2.getl?.(current)?.es?.filter((card2) => get.suit(card2) == "spade");
          if (cards2?.length) {
            num += cards2.length;
          }
        });
        await player2.recover(num);
      }
    }
  }

