      await player2.recast(result.cards);
      const source = trigger2.source;
      if (source?.isIn()) {
        player2.line(source);
        const resultx = await source.chooseToGive(player2, "e", "蓍算：交给" + get.translation(player2) + "一张装备区的牌，或失去1点体力或将武将牌翻面").set("ai", (card2) => {
