            return 0;
          }
          return 8 - get.value(card2);
        }).forResult();
        if (!resultx?.bool) {
          const result2 = await source.chooseControl("失去体力", "翻面").set("ai", () => {
            const player3 = get.player(), target2 = get.event().getParent().player;
            if (player3.isTurnedOver()) {
              return 0;
            }
            return get.effect(player3, { name: "losehp" }, player3, player3) > 0 ? 0 : (() => {
              if (player3.hasCard((card2) => get.tag(card2, "damage") && player3.canUse(card2, target2, true, true) && player3.getCardUsable(get.name(card2)) >= 2 && get.effect(target2, card2, player3, player3) > 0, "hs")) {
                return 1;
              }
              return player3.getHp() + player3.countCards("hs", { name: "tao" }) <= 2 ? 1 : 0;
            })();
          }).set("prompt", "失去1点体力或将武将牌翻面").forResult();
          if (result2.index === 0) {
            await source.loseHp();
          } else {
            await source.turnOver();
          }
        }
      }
    },
    ai: {
      maixie: true,
      maixie_hp: true,
      effect: {
        target(card2, player2, target2) {
          if (_status._olshisuan_temp) {
            return;
          }
          if (get.tag(card2, "damage")) {
            if (player2.hasSkillTag("jueqing", false, target2) || get.effect(player2, { name: "losehp" }, player2, player2) > 0 || player2.isTurnedOver()) {
              return [1, -2];
            }
            if (player2.hasCard(
              (cardx) => get.tag(cardx, "damage") && player2.canUse(cardx, target2, true, true) && !((card3) => {
                let list = [card3];
                if (card3.cards) {
                  list.addArray(card3.cards);
                }
                return list;
              })(card2).includes(cardx) && player2.getCardUsable(get.name(card2)) >= 2 && (() => {
                _status._olshisuan_temp = true;
                let eff = get.effect(target2, card2, player2, player2) > 0;
                delete _status._olshisuan_temp;
                return eff;
              })(),
              "hs"
            )) {
              return [1, -2];
            }
            return [1, -0.5];
          }
        }
      }
    }
  }

