sp:olkuangxiang.code:
{
    audio: 2,
    trigger: { player: "phaseZhunbeiBegin" },
    filter(event2, player2) {
      return game.hasPlayer((target2) => target2.countCards("h") !== 4);
    },
    async cost(event2, trigger2, player2) {
      event2.result = await player2.chooseTarget({
        prompt: get.prompt2(event2.skill),
        filterTarget(card2, player3, target2) {
          return target2.countCards("h") !== 4;
        },
        ai(target2) {
          const att = get.attitude(get.player(), target2);
          const num = target2.countCards("h");
          if (num > 4) {
            return -att * (num - 4);
          }
          return att * Math.max(0, 4 - target2.countCards("h"));
        }
      }).forResult();
    },
    async content(event2, trigger2, player2) {
      const target2 = event2.targets[0];
      const num = target2.countCards("h");
      if (num > 4) {
        await target2.chooseToDiscard("h", num - 4, true, "allowChooseAll");
      } else {
        const cards2 = (await target2.draw(4 - num).forResult()).cards;
        if (Array.isArray(cards2) && cards2.length) {
          const black = cards2.filter((card2) => get.color(card2) === "black");
          const red = cards2.filter((card2) => get.color(card2) === "red").length;
          if (black.length) {
            target2.addSkill("olkuangxiang_effect");
            target2.addGaintag(black, "olkuangxiang_effect");
          }
          if (red > 0) {
            target2.addSkill("olkuangxiang_buff");
            target2.addMark("olkuangxiang_buff", red, false);
          }
        }
      }
    },
    subSkill: {
      effect: {
        charlotte: true,
        trigger: { source: "damageBegin1" },
        filter(event2, player2) {
          if (!event2.card) {
            return false;
          }
          const evt = event2.getParent("useCard");
          if (!evt || evt.card !== event2.card || evt.cards?.length !== 1) {
            return false;
          }
          return player2.hasHistory("lose", (evtx) => (evtx.relatedEvent || evtx.getParent()) === evt && Object.keys(evtx.gaintag_map).some((i) => evtx.gaintag_map[i].includes("olkuangxiang_effect")));
        },
        forced: true,
        logTarget: "player",
        content() {
          trigger.num++;
        }
      },
      buff: {
        charlotte: true,
        onremove: true,
        intro: { content: "下个摸牌阶段少摸#张牌" },
        trigger: { player: "phaseDrawBegin1" },
        filter(event2, player2) {
          return !event2.numFixed;
        },
        forced: true,
        content() {
          trigger.num -= player.countMark(event.name);
          player.removeSkill(event.name);
        }
      }
    }
  }

sp:olrenxia.code:
{
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    chooseButton: {
      dialog(event2, player2) {
        var dialog = ui.create.dialog("任侠：请选择一项", "hidden");
        dialog.add([
          [
            ["discard", "重复弃置两张牌，直至手牌中没有【杀】或伤害类锦囊牌"],
            ["draw", "重复摸两张牌，直至手牌中有【杀】或伤害类锦囊牌"]
          ],
          "textbutton"
        ]);
        return dialog;
      },
      filter(button, player2) {
        if (button.link == "discard") {
          return player2.hasCard((card2) => {
            if (!lib.filter.cardDiscardable(card2, player2, "renxia_discard")) {
              return false;
            }
            return card2.name == "sha" || get.type(card2) == "trick" && get.tag(card2, "damage") && get.type(card2) != "delay";
          }, "he");
        }
        return true;
      },
      check(button) {
        const player2 = get.player();
        if (button.link == "discard") {
          return 2;
        }
        let bool = (card2) => get.type(card2) == "trick" && get.tag(card2, "damage") && get.type(card2) != "delay";
        if (player2.countCards("h", "sha") > 1 && player2.countCards("h", bool) > 1) {
          return 1;
        }
        return 3;
      },
      backup(links) {
        return get.copy(lib.skill["olrenxia_" + links[0]]);
      }
    },
    subSkill: {
      backup: { audio: "olrenxia" },
      discard: {
        audio: "olrenxia",
        async content(event2, trigger2, player2) {
          while (true) {
            if (player2.hasCard((card2) => {
              if (!lib.filter.cardDiscardable(card2, player2, "renxia_discard")) {
                return false;
              }
              return card2.name == "sha" || get.type(card2) == "trick" && get.tag(card2, "damage") && get.type(card2) != "delay";
            }, "he")) {
              await player2.chooseToDiscard(2, "he", true).set("ai", (card2) => {
                get.player();
                let bool = (card3) => get.type(card3) == "trick" && get.tag(card3, "damage") && get.type(card3) != "delay";
                if (card2.name == "sha" || bool(card2)) {
                  return 10 - get.value(card2);
                }
                return 5 - get.value(card2);
              });
            } else {
              break;
            }
          }
          const evt = event2.getParent("phaseUse", true);
          if (!evt || event2.name == "renxia_discard") {
            return;
          }
          player2.when("phaseUseEnd").filter((evtx) => evtx == evt).step(async () => {
            const next = game.createEvent("renxia_draw", false);
            next.player = player2;
            next.setContent(lib.skill.olrenxia_draw.content);
          });
        }
      },
      draw: {
        audio: "olrenxia",
        async content(event2, trigger2, player2) {
          while (true) {
            await player2.draw(2);
