        const player2 = event2.player;
        let basic = lib.inpile.filter((i) => get.type(i) == "basic");
        player2.getRoundHistory("useCard", (evt) => {
          if (get.type(evt.card) == "basic") {
            basic.remove(evt.card.name);
          }
        });
        event2.set("leiluan", [basic, lib.skill.leiluan.getNum()]);
      }
    },
    getNum() {
      return Math.max(
        1,
        game.countPlayer((current) => current.isLinked())
      );
    },
    enable: "chooseToUse",
    filter(event2, player2) {
      if (!event2.leiluan || player2.countCards("hes") < event2.leiluan[1] || event2.type == "wuxie") {
        return false;
      }
      return get.inpileVCardList((info) => {
        const name = info[2], type = get.type(name);
        return type == "basic" && event2.leiluan[0].includes(name);
      }).some((card2) => {
        return event2.filterCard({ name: card2[2], nature: card2[3] }, player2, event2);
      });
    },
    chooseButton: {
      dialog(event2, player2) {
        const list = get.inpileVCardList((info) => {
          const name = info[2], type = get.type(name);
          return type == "basic" && event2.leiluan[0].includes(name);
        }).filter((card2) => {
          return event2.filterCard({ name: card2[2], nature: card2[3] }, player2, event2);
        });
        return ui.create.dialog("累卵", [list, "vcard"]);
      },
      check(button) {
        if (get.event().getParent().type != "phase") {
          return 1;
        }
        return get.player().getUseValue({ name: button.link[2], nature: button.link[3] });
      },
      backup(links, player2) {
        return {
          audio: "leiluan",
          filterCard: true,
          selectCard: get.event().leiluan[1],
          check(card2) {
            return 1 / (get.value(card2) || 0.5);
          },
          viewAs: {
            name: links[0][2],
            nature: links[0][3]
          },
          position: "hes",
          popname: true,
          allowChooseAll: true,
          async precontent(event2, trigger2, player3) {
            player3.addTempSkill("leiluan_effect");
          }
        };
      },
      prompt(links) {
        return "将" + get.cnNumber(get.event().leiluan[1]) + "张牌当作" + (get.translation(links[0][3]) || "") + "【" + get.translation(links[0][2]) + "】使用";
      }
    },
    hiddenCard(player2, name) {
      if (player2.getStat("skill").leiluan) {
        return false;
      }
      let basic = lib.inpile.filter((i) => get.type(i) == "basic");
      player2.getRoundHistory("useCard", (evt) => {
        if (get.type(evt.card) == "basic") {
          basic.remove(evt.card.name);
        }
      });
      const num = lib.skill.leiluan.getNum();
      return basic.includes(name) && player2.countCards("hes") >= num;
    },
    ai: {
      order(item, player2) {
        if (player2 && get.event().type == "phase") {
          let list = get.inpileVCardList((info) => {
            return get.info("leiluan").hiddenCard(player2, info[2]);
          }).map((card2) => {
            return { name: card2[2], nature: card2[3] };
          }).filter((card2) => player2.getUseValue(card2, true, true) > 0);
          if (!list.length) {
            return 0;
          }
          list.sort((a, b) => {
            return player2.getUseValue(b, true, true) - player2.getUseValue(a, true, true);
          });
          return get.order(list[0], player2) * 1.01;
        }
        return 1e-3;
      },
      respondSha: true,
      respondShan: true,
      skillTagFilter(player2, tag, arg) {
        if (arg === "respond") {
          return false;
        }
        const name = tag == "respondSha" ? "sha" : "shan";
        return get.info("leiluan").hiddenCard(player2, name);
      },
      result: {
        player: 1
      }
    },
    subSkill: {
      backup: {},
      effect: {
        trigger: {
          player: "loseAfter",
          global: ["equipAfter", "addJudgeAfter", "gainAfter", "loseAsyncAfter", "addToExpansionAfter"]
        },
        charlotte: true,
        forced: true,
        locked: false,
        popup: false,
        filter(event2, player2) {
          if (event2.getParent().skill !== "leiluan_backup" || player2.countCards("h")) {
            return false;
          }
          const evt = event2.getl(player2);
          return evt && evt.player === player2 && evt.hs && evt.hs.length;
        },
        async content(event2, trigger2, player2) {
          await player2.draw(2);
          let cards2 = get.discarded().filter((c) => get.type(c) === "trick");
          if (cards2?.length) {
            const result = await player2.chooseButton(["累卵：获得一张普通锦囊牌", cards2], true).set("ai", (button) => get.buttonValue(button)).forResult();
            if (result?.bool && result?.links?.length) {
              await player2.gain(result.links, "gain2");
            }
          }
          player2.tempBanSkill("leiluan", { player: "damageEnd" });
        }
      }
    }
  }

