    multitarget: true,
    multiline: true,
    async content(event2, trigger2, player2) {
      const targets2 = event2.targets.sortBySeat();
      let answer_result = [[], []];
      const map = await game.chooseAnyOL(targets2, get.info(event2.name).chooseControl, [player2]).forResult();
      for (const i of targets2) {
        i.addExpose(0.05);
        const result = map.get(i).control;
        if (result == "成为目标") {
          answer_result[0].push(i);
        } else {
          answer_result[1].push(i);
        }
        i.popup(result);
        game.log(i, "选择了", "#y" + result);
      }
      await game.delay();
      if (answer_result[0].length) {
        answer_result[0].sortBySeat();
        player2.addTempSkill("olhunjiang_addTarget");
        player2.markAuto("olhunjiang_addTarget", answer_result[0]);
        if (!answer_result[1].length) {
          await player2.draw(answer_result[0].length);
        }
      }
      if (answer_result[1].length) {
        answer_result[1].sortBySeat();
        await player2.draw(answer_result[1].length);
        if (!answer_result[0].length) {
          player2.addTempSkill("olhunjiang_addTarget");
          player2.markAuto("olhunjiang_addTarget", answer_result[1]);
        }
      }
    },
    ai: {
