        }
      }
    },
    chooseControl(player2, source, eventId) {
      const str = get.translation(source);
      return player2.chooseControl("成为目标", "令其摸牌").set("prompt", "###" + str + '对你发动了【浑疆】，请选择一项###<div class="text center">若所有角色选择了同一项，则所有角色也执行另一项</div>').set("choiceList", ["令" + str + "本阶段使用【杀】可以额外指定你为目标", "令" + str + "摸一张牌"]).set("source", source).set("id", eventId).set("_global_waiting", true).set("ai", () => get.event().idx).set(
        "idx",
        (function() {
          let cha = get.effect(player2, { name: "sha" }, source, player2) * source.mayHaveSha(player2, "use", null, "odds") - get.effect(player2, { name: "draw" }, source, player2);
