sp:olzuolian.code:
{
    audio: 2,
    enable: "phaseUse",
    filter(event2, player2) {
      return player2.getHp() > 0 && game.hasPlayer((target2) => target2.countCards("h"));
    },
    filterTarget(card2, player2, target2) {
      return target2.countCards("h");
    },
    selectTarget() {
      return [1, get.event().player.getHp()];
    },
    usable: 1,
    multitarget: true,
    multiline: true,
    async content(event2, trigger2, player2) {
      const targets2 = event2.targets.sortBySeat();
      const cards2 = targets2.slice().map((i) => i.getCards("h").randomGet());
      const next = player2.showCards(cards2, get.translation(player2) + "发动了【佐练】").set("customButton", (button) => {
        const target2 = get.owner(button.link);
        button.querySelector(".info").innerHTML = target2.getName();
      }).set("log", (cards3, player3) => [player3, "展示了", cards3.map((card2) => get.owner(card2)), "的", cards3]).set("delay_time", Math.min(targets2.length * 2.5, 7.5)).set("closeDialog", false);
      await next;
      const id = next.videoId;
      const update = (id2) => {
        const dialog = get.idDialog(id2);
        if (dialog) {
          const div = dialog.querySelector(".caption");
          div.innerHTML = "是否将这些牌与牌堆或弃牌堆中的属性杀交换？";
          ui.update();
        }
      };
      if (player2.isOnline2()) {
        player2.send(update, id);
      } else {
        update(id);
      }
      const result = await player2.chooseBool().set("dialog", get.idDialog(id)).forResult();
      game.broadcastAll("closeDialog", id);
      if (!result?.bool) {
        return;
      }
      const cards_cardPile = Array.from(ui.cardPile.childNodes).filter((i) => i.name == "sha" && get.nature(i, false));
      const cards_discardPile = Array.from(ui.discardPile.childNodes).filter((i) => i.name == "sha" && get.nature(i, false));
      let hasFire = true;
      for (let i = 0; i < targets2.length; i++) {
        let target2 = targets2[i];
        let card2 = cards2[i];
        let cardx;
        if (hasFire) {
          let cardxs = get.cardPile((card3) => {
            return card3.name == "sha" && game.hasNature(card3, "fire");
          });
          if (cardxs) {
            cardx = cardxs;
          } else {
            hasFire = false;
          }
        }
        if (!hasFire) {
          let cardxs = get.cardPile((card3) => {
            return card3.name == "sha" && get.nature(card3, false);
          });
          if (cardxs) {
            cardx = cardxs;
          } else {
            player2.popup("杯具");
            player2.chat("我属性【杀】呢？！");
            game.log("但牌堆和弃牌堆都没有属性【杀】！");
            return;
          }
        }
        if (!cardx) {
          return;
        }
        let position;
        if (cards_cardPile.includes(cardx)) {
          position = "牌堆";
          target2.$throw([card2], 1e3);
          await target2.lose([card2], ui.cardPile).set("insert_index", () => {
            return ui.cardPile.childNodes[get.event().num];
          }).set("num", cards_cardPile.indexOf(cardx));
        } else if (cards_discardPile.includes(cardx)) {
          position = "弃牌堆";
          await target2.loseToDiscardpile(card2);
        }
        game.log(target2, "将", cards2[i], `与${position}的`, cardx, "交换");
        await target2.gain(cardx, "gain2").set("log", false);
      }
    },
    ai: {
      order: 10,
      result: {
        target(player2, target2) {
          return 0.5 - Math.random();
        }
      }
    }
  }

