{
    getCoordinate(player2) {
      const dialog = ui[`olremaozhuMap_${player2.playerid}`];
      const cell = dialog?.playerPosition;
      if (!dialog || !cell) {
        return null;
      }
      const absX = Number(cell.dataset.x);
      const absY = Number(cell.dataset.y);
      const height = dialog.querySelectorAll(".olremaozhuRow").length;
      const newX = absX + 1;
      const newY = height - absY;
      return `${newX},${newY}`;
    },
    canJinlan(card2, player2) {
      const dialog = ui[`olremaozhuMap_${player2.playerid}`];
      if (!dialog) {
        return false;
      }
      const suit = get.suit(card2);
      const pos = lib.skill.olrejinlan.getCoordinate(player2);
      const map = dialog?.querySelector(".olremaozhuTitle")?.innerHTML;
      const canUse = (lib.skill.olremaozhu.bestLine[map] || []).some((route) => {
        return route.some((step) => {
          if (step.start !== pos) {
            return false;
          }
          if (step.suit !== suit) {
            return false;
          }
          if (step.filter && !step.filter(dialog)) {
            return false;
          }
          return true;
        });
      });
      return canUse;
    },
    mod: {
      aiOrder(player2, card2, num) {
        if (typeof card2 == "object") {
          if (lib.skill.olrejinlan.canJinlan(card2, player2) && player2 === _status.currentPhase) {
            return num + 10;
          }
        }
      }
    },
    locked: false,
    audio: 2,
    trigger: { player: "useCardAfter" },
    filter(event2, player2) {
      if (player2 !== _status.currentPhase) return false;
      const dialog = ui[`olremaozhuMap_${player2.playerid}`];
      const suit = get.suit(event2.card);
      if (!lib.suit.includes(suit) || !dialog?.playerPosition) {
        return false;
      }
      const list = { spade: [1, 0], heart: [-1, 0], club: [0, 1], diamond: [0, -1] }[suit];
      const cell = dialog.querySelector(`[data-x='${Number(dialog.playerPosition.dataset.x) + list[0]}'][data-y='${Number(dialog.playerPosition.dataset.y) + list[1]}']`);
      return cell && cell.style.visibility !== "hidden";
    },
    prompt2(event2, player2) {
      const suit = get.suit(event2.card);
      const dialog = ui[`olremaozhuMap_${player2.playerid}`];
      const map = dialog?.querySelector(".olremaozhuTitle")?.innerHTML || "滚木";
      return `向${{ spade: "东", heart: "西", club: "南", diamond: "北" }[suit]}探索${map}的所有地图`;
    },
    check(event2, player2) {
      return lib.skill.olrejinlan.canJinlan(event2.card, player2);
    },
    async content(event2, trigger2, player2) {
      const suit = get.suit(trigger2.card);
      const list = { spade: [1, 0], heart: [-1, 0], club: [0, 1], diamond: [0, -1] }[suit];
      const dialog = ui[`olremaozhuMap_${player2.playerid}`];
      if (!dialog) {
        return;
      }
      function moveCell(playerid, targetCellX, targetCellY) {
        const dialog2 = ui[`olremaozhuMap_${playerid}`];
        if (!dialog2?.playerPosition) {
          return;
        }
        const old = dialog2.playerPosition;
        const targetCell = dialog2.querySelector(`[data-x='${targetCellX}'][data-y='${targetCellY}']`);
        if (!targetCell) {
          return;
        }
        old.innerHTML = "";
        old.style.backgroundImage = "";
        old.style.background = "rgba(255,255,255,0.15)";
        old.querySelectorAll(".olremaozhuArrow").forEach((node) => node.remove());
        if (targetCell.dataset.event) {
          delete targetCell.dataset.event;
          delete targetCell.dataset.score;
          delete targetCell.dataset.cityName;
        }
        targetCell.innerHTML = "";
        targetCell.style.backgroundImage = "";
        targetCell.setBackground("ol_peixiu", "character");
        lib.skill.olremaozhu.createArrow(targetCell);
        dialog2.playerPosition = targetCell;
        const map = dialog2.querySelector(".olremaozhuTitle").innerHTML;
        const city = lib.skill.olremaozhu.updateCityString(dialog2);
        lib.skill.olremaozhu.updateReconnect(playerid, map, city);
      }
      let effect = [];
      while (true) {
        const oldCell = dialog.playerPosition;
        if (!oldCell) {
          break;
        }
        const cell = dialog.querySelector(`[data-x='${Number(oldCell.dataset.x) + list[0]}'][data-y='${Number(oldCell.dataset.y) + list[1]}']`);
        if (cell && cell.style.visibility !== "hidden") {
          if (cell.dataset.event) {
            effect.push([cell.dataset.event, cell.dataset.score, cell.dataset.cityName]);
            game.log(player2, "已绘制", `#g${get.translation(cell.dataset.cityName)}`);
          }
          game.broadcastAll(moveCell, player2.playerid, cell.dataset.x, cell.dataset.y);
          await game.delay(0.25);
        } else {
          break;
        }
      }
      let num = 0;
      while (effect[num]) {
        let [eventName, score, cityName] = effect[num];
        player2.addTempSkill(event2.name + "_map");
        player2.markAuto(event2.name + "_map", [cityName]);
        num++;
        score = Number(score);
        if (["draw", "recover"].includes(eventName)) {
          await player2[eventName](score);
        } else {
          for (let count = 0; count < score; count++) {
            const dialog2 = ui[`olremaozhuMap_${player2.playerid}`];
            if (!dialog2) {
              return;
            }
            const oldCell = dialog2.playerPosition;
            const list2 = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }[eventName];
            const cell = dialog2.querySelector(`[data-x='${Number(oldCell.dataset.x) + list2[0]}'][data-y='${Number(oldCell.dataset.y) + list2[1]}']`);
            if (cell && cell.style.visibility !== "hidden") {
              if (cell.dataset.event) {
                effect.push([cell.dataset.event, cell.dataset.score, cell.dataset.cityName]);
                game.log(player2, "已绘制", `#g${get.translation(cell.dataset.cityName)}`);
              }
              game.broadcastAll(moveCell, player2.playerid, cell.dataset.x, cell.dataset.y);
              await game.delay(0.25);
            } else {
              break;
            }
          }
        }
      }
      if (!ui[`olremaozhuMap_${player2.playerid}`]?.querySelector("[data-event]")) {
        await event2.trigger("maozhuSuccess");
      }
    },
    ai: {
      combo: "olremaozhu",
      effect: {
        player_use(card2, player2, target2) {
          if (typeof card2 !== "object" || !lib.skill.olrejinlan.canJinlan(card2, player2) || player2 !== _status.currentPhase) {
            return;
          }
          return [1, 0.8];
        }
      }
    },
    subSkill: {
      map: {
        charlotte: true,
        onremove: true,
        intro: {
          content(storage = [], player2) {
            if (!storage?.length) {
              return "当前暂未游览任何城市";
            }
            let str = `<li>本回合已触发效果城市：${storage.map((city) => get.translation(city)).join("、")}`;
            const list = [];
            const mapSkill = get.info("olremaozhu").mapSkill;
            for (const map of Array.from(mapSkill.keys())) {
              if (mapSkill.get(map).every((city) => storage.slice().includes(city))) {
                list.add(map);
              }
            }
            if (list.length) {
              str += `<br><li>本回合已绘制地图：${list.map((map) => get.translation(map)).join("、")}`;
            }
            return str;
          }
        }
      }
    }
  }

