          nature: links[0][3],
          suit: "none",
          number: null,
          isCard: true
        };
        next.viewAs = viewAs;
        if (get.info("xunshi").isXunshi(viewAs)) {
          next.filterTarget = function(card2, player3, target2) {
            const info = get.info(card2);
            if (info.changeTarget) {
              let targets2 = [target2];
              info.changeTarget(player3, targets2);
              if (targets2.length > 1) {
                return false;
              }
            }
            return lib.filter.filterTarget(card2, player3, target2);
          };
          next.selectTarget = 1;
        }
        return next;
      },
      prompt(links, player2) {
        const viewAs = {
          name: links[0][2],
          nature: links[0][3],
          suit: "none",
          number: null,
          isCard: true
        };
        const str = "将一张牌称为“玄”置于武将牌上，然后视为使用" + (get.translation(links[0][3]) || "") + "【" + get.translation(links[0][2]) + "】";
        return str + (get.info("xunshi").isXunshi(viewAs) ? "（仅能指定一个目标）" : "");
      }
    },
    hiddenCard(player2, name) {
      if (!lib.inpile.includes(name) || player2.getStat("skill").olxuanzhu || !player2.countCards("he")) {
        return false;
      }
      return get.inpileVCardList((info) => {
        const name2 = info[2], type = get.type(name2), infox = get.info({ name: name2 });
        if (type != "basic" && type != "trick") {
          return false;
        }
        if (type == "trick" && (!infox || !infox.filterTarget || get.info("xunshi").isXunshi({ name: name2 }))) {
          return false;
        }
        return type != "basic" == (player2.storage.olxuanzhu || false);
      }).map((card2) => card2[2]).includes(name);
    },
    ai: {
      order(item, player2) {
        if (player2 && get.event().type == "phase") {
          let list = get.inpileVCardList((info) => {
            const name = info[2], type = get.type(name), infox = get.info({ name });
            if (type != "basic" && type != "trick") {
              return false;
            }
            if (type == "trick" && (!infox || !infox.filterTarget || get.info("xunshi").isXunshi({ name }))) {
              return false;
            }
            return type != "basic" == (player2.storage.olxuanzhu || false);
          }).map((card2) => {
            return { name: card2[2], nature: card2[3] };
          }).filter((card2) => player2.getUseValue(card2, true, true) > 0);
          if (!list.length) {
            return 0;
          }
          list.sort((a, b) => {
            const getNum = function(card2) {
              if (get.info("xunshi").isXunshi(card2)) {
                return get.effect(
                  game.filterPlayer((target2) => {
                    return player2.canUse(card2, target2, true, true);
                  }).sort((a2, b2) => get.effect(b2, card2, player2, player2) - get.effect(a2, card2, player2, player2))[0],
                  card2,
                  player2,
                  player2
                );
              }
              return player2.getUseValue(card2, true, true);
            };
            return (getNum(b) || 0) - (getNum(a) || 0);
          });
          return get.order(list[0], player2) * 0.99;
        }
        return 1e-3;
      },
      respondSha: true,
      respondShan: true,
      skillTagFilter(player2, tag, arg) {
        if (arg == "respond") {
          return false;
        }
        const name = tag == "respondSha" ? "sha" : "shan";
        return get.info("olxuanzhu").hiddenCard(player2, name);
      },
      result: { player: 1 }
    },
    intro: {
      markcount: "expansion",
      mark(dialog, storage, player2) {
        const cards2 = player2.getExpansions("olxuanzhu");
        if (cards2.length) {
          dialog.addSmall(player2.getExpansions("olxuanzhu"));
        }
        dialog.addText(
          (() => {
            if (storage) {
              return "每回合限一次，你可以将一张牌称为“玄”置于武将牌上，然后视为使用任意普通锦囊牌（须指定目标且仅指定一个目标）。若此次置于武将牌上的“玄”：不为装备牌，你弃置一张牌；为装备牌，你将所有“玄”置入弃牌堆，然后摸等量的牌。";
            }
            return "每回合限一次，你可以将一张牌称为“玄”置于武将牌上，然后视为使用任意基本牌。若此次置于武将牌上的“玄”：不为装备牌，你弃置一张牌；为装备牌，你将所有“玄”置入弃牌堆，然后摸等量的牌。";
          })()
        );
      }
    },
    onremove(player2, skill) {
      const cards2 = player2.getExpansions(skill);
      if (cards2.length) {
        player2.loseToDiscardpile(cards2);
      }
    },
    subSkill: { backup: {} }
  }

