      return (event2.card.name == "sha" || get.type(event2.card) == "trick") && event2.targets.length == 1;
    },
    usable: 1,
    locked: false,
    async cost(event2, trigger2, player2) {
      const num = Math.max(1, player2.getDamagedHp());
      event2.result = await player2.chooseTarget(get.prompt(event2.skill), [1, num], (card2, player3, target2) => {
        const trigger3 = get.event().getTrigger();
        if (target2 == player3) {
          return false;
        }
        if (trigger3.targets.includes(target2)) {
          return true;
        }
        return lib.filter.targetEnabled2(trigger3.card, player3, target2) && lib.filter.targetInRange(trigger3.card, player3, target2);
      }).set("ai", (target2) => {
        const player3 = get.event().player, trigger3 = get.event().getTrigger();
        return (trigger3.targets.includes(target2) ? -1 : 1) * get.effect(target2, trigger3.card, player3, player3) * (target2.getStorage("olpijing_effect").includes(player3) ? 2 : 1) + get.effect(target2, { name: "shunshou_copy2" }, player3, player3);
      }).set("prompt2", "令至多" + get.cnNumber(num) + "名角色成为或取消成为" + get.translation(trigger2.card) + "的目标并随机交给你一张牌").forResult();
    },
    async content(event2, trigger2, player2) {
      const targets2 = event2.targets;
      for (const i of targets2) {
        trigger2.targets[!trigger2.targets.includes(i) ? "add" : "remove"](i);
      }
      for (const target2 of targets2) {
        target2.addSkill("olpijing_effect");
        target2.markAuto("olpijing_effect", [player2]);
        const cards2 = target2.getGainableCards(player2, "he");
        if (cards2.length) {
          await target2.give(cards2.randomGets(1), player2);
        }
      }
    },
    mod: {
      aiOrder(player2, card2, num) {
        if (!(card2.name == "sha" || get.type(card2) == "trick")) {
          return;
        }
        const info = get.info(card2);
        if (info && !info.notarget && (info.toself || info.singleCard || !info.selectTarget || info.selectTarget == 1) && game.countPlayer((target2) => {
          if (get.effect(target2, card2, player2, player2) <= 0) {
            return false;
          }
          return lib.filter.targetEnabled2(card2, player2, target2) && lib.filter.targetInRange(card2, player2, target2);
        }) > 1) {
          return num + 0.01;
        }
      }
    },
    subSkill: {
      effect: {
        charlotte: true,
        onremove: true,
        intro: {
          content: "使用的下一张基本牌或普通锦囊牌指定唯一目标时，可指定$为额外目标或摸一张牌"
        },
        trigger: { player: "useCardToPlayer" },
        filter(event2, player2) {
          return (get.type(event2.card) == "basic" || get.type(event2.card) == "trick") && event2.targets.length == 1;
        },
        forced: true,
        popup: false,
        async content(event2, trigger2, player2) {
          const storage = player2.getStorage("olpijing_effect");
          player2.removeSkill("olpijing_effect");
          const { bool, targets: targets2 } = await player2.chooseTarget("披荆：请选择此牌的额外目标", [1, storage.length], (card2, player3, target2) => {
            const trigger3 = get.event().getTrigger();
            return !trigger3.targets.includes(target2) && get.event().storage.includes(target2) && lib.filter.targetEnabled2(trigger3.card, player3, target2) && lib.filter.targetInRange(trigger3.card, player3, target2);
          }).set("prompt2", "不选择的角色视为你选择摸牌项").set("ai", (target2) => {
            const player3 = get.event().player, trigger3 = get.event().getTrigger();
            return get.effect(target2, trigger3.card, player3, player3) - get.effect(player3, { name: "draw" }, player3, player3);
          }).set("storage", storage).forResult();
          if (bool) {
            player2.line(targets2);
            trigger2.targets.addArray(targets2);
            if (storage.length - targets2.length > 0) {
              player2.draw(storage.length - targets2.length);
            }
          } else {
            player2.draw(storage.length);
          }
        }
      }
    }
  }

