              return get.distance(player4, target2) == 1 && target2.countDiscardableCards(player4, "h");
            }).set("ai", (target2) => 1 - get.sgn(get.attitude(get.event().player, target2))).forResult();
            if (result?.bool) {
              const target2 = result.targets[0];
              player3.logSkill("olweijie", target2);
              player3.tempBanSkill("olweijie", null, false);
              const result2 = await player3.discardPlayerCard(target2, "h", true).set("prompt2", "若弃置的牌名为【" + get.translation(event2.result.card.name) + "】，则视为你使用/打出之").set("ai", (button) => {
                if (button.link.isKnownBy(get.event().player) && button.link.name == get.event().namex) {
                  return 114514;
                }
                return 1 + Math.random();
              }).set("namex", event2.result.card.name).forResult();
              if (result2?.bool) {
                const card2 = result2.cards[0];
                if (get.name(card2, target2) == event2.result.card.name) {
                  player3.popup("洗具");
                  stop = true;
                } else {
                  player3.popup("杯具");
                }
