      if (!player2.countCards("h", (card2) => card2.hasGaintag("olchongshen") && get.color(card2) == "red")) {
        return false;
      }
    },
    prompt: "将本轮得到的红色牌当作【闪】使用",
    check(card2) {
      return 7 - get.value(card2);
    },
    ai: {
      order: 2,
      respondShan: true,
      skillTagFilter(player2, tag, arg) {
        if (arg == "respond" || !player2.countCards("h", (card2) => _status.connectMode || card2.hasGaintag("olchongshen") && get.color(card2) == "red")) {
          return false;
        }
      },
      effect: {
        target(card2, player2, target2, current) {
          if (get.tag(card2, "respondShan") && current < 0) {
            return 0.6;
          }
        }
      }
    },
    group: "olchongshen_mark",
    mod: {
      aiValue(player2, card2, num) {
        if (get.name(card2) != "shan" && get.itemtype(card2) == "card" && (!card2.hasGaintag("olchongshen") || get.color(card2) != "red")) {
          return;
        }
        let cards2 = player2.getCards("hs", (card3) => get.name(card3) == "shan" || card3.hasGaintag("olchongshen"));
        cards2.sort((a, b) => (get.name(b) == "shan" ? 1 : 2) - (get.name(a) == "shan" ? 1 : 2));
        const geti = () => {
          if (cards2.includes(card2)) {
            return cards2.indexOf(card2);
          }
          return cards2.length;
        };
        if (get.name(card2) == "shan") {
          return Math.min(num, [6, 4, 3][Math.min(geti(), 2)]) * 0.6;
        }
        return Math.max(num, [6.5, 4, 3][Math.min(geti(), 2)]);
      },
      aiUseful() {
        return lib.skill.olchongshen.mod.aiValue.apply(this, arguments);
      }
      // ignoredHandcard(card,player){
      // 	if(card.hasGaintag('olchongshen')) return true;
      // },
      // cardDiscardable(card,player,name){
      // 	if(name=='phaseDiscard'&&card.hasGaintag('olchongshen')) return false;
      // },
    },
    init(player2) {
      if (game.phaseNumber > 0) {
        const hs = player2.getCards("h"), history = player2.getAllHistory();
        let cards2 = [];
        for (let i = history.length - 1; i >= 0; i--) {
          for (const evt of history[i].gain) {
            cards2.addArray(evt.cards);
          }
          if (history[i].isRound) {
            break;
          }
        }
        cards2 = cards2.filter((i) => hs.includes(i));
        if (cards2.length) {
          player2.addGaintag(cards2, "olchongshen");
        }
      }
    },
    onremove(player2) {
      player2.removeGaintag("olchongshen");
    },
    subSkill: {
      mark: {
        charlotte: true,
        trigger: { player: "gainBegin", global: "roundStart" },
        filter(event2, player2) {
          return event2.name == "gain" || game.roundNumber > 1;
        },
        forced: true,
        popup: false,
        content() {
          if (trigger.name == "gain") {
            trigger.gaintag.add("olchongshen");
          } else {
            player.removeGaintag("olchongshen");
          }
        }
      }
    }
  }

