sp:olshandao.code:
{
    audio: 2,
    enable: "phaseUse",
    filter(event2, player2) {
      return game.hasPlayer((target2) => lib.skill.olshandao.filterTarget(null, player2, target2));
    },
    filterTarget(card2, player2, target2) {
      return target2.countCards("hej");
    },
    usable: 1,
    selectTarget: [1, Infinity],
    multitarget: true,
    multiline: true,
    async content(event2, trigger2, player2) {
      const wugu = new lib.element.VCard({ name: "wugu", isCard: true });
      const wanjian = new lib.element.VCard({ name: "wanjian", isCard: true });
      const targets2 = game.filterPlayer((target2) => {
        if (target2 == player2) {
          return false;
        }
        return !event2.targets.includes(target2) && player2.canUse(wanjian, target2, false);
      }), targetx = event2.targets.sortBySeat();
      let dialog = ["将这些角色的各一张牌置于牌堆顶，然后视为对这些角色使用【五谷丰登】"];
      for (const target2 of targetx) {
        const name = target2 == player2 ? "你" : get.translation(target2);
        if (target2.countCards("h")) {
          dialog.add('<div class="text center">' + name + "的手牌区</div>");
          if (player2.hasSkillTag("viewHandcard", null, target2, true) || player2 == target2) {
            dialog.push(target2.getCards("h"));
          } else {
            dialog.push([target2.getCards("h"), "blank"]);
          }
        }
        if (target2.countCards("e")) {
          dialog.addArray(['<div class="text center">' + name + "的装备区</div>", target2.getCards("e")]);
        }
        if (target2.countCards("j")) {
          dialog.addArray(['<div class="text center">' + name + "的判定区</div>", target2.getCards("j")]);
        }
      }
      const { bool, links } = await player2.chooseButton(dialog, event2.targets.length, true).set("filterButton", (button) => {
        return !ui.selected.buttons.some((but) => get.owner(but.link) == get.owner(button.link));
      }).set("ai", (button) => 1 / (get.value(button.link, get.owner(button.link)) || 0.5)).forResult();
      if (bool) {
        const cards2 = links.sort((a, b) => targetx.indexOf(get.owner(a)) - targetx.indexOf(get.owner(b)));
        for (const card2 of cards2) {
          const target2 = get.owner(card2);
          target2.$throw(1, 1e3);
          await target2.lose([card2], ui.cardPile, "insert");
        }
        const targety = targetx.filter((target2) => player2.canUse(wugu, target2, false));
        if (targety.length) {
          await player2.useCard(wugu, targety, false);
        }
        if (targets2.length) {
          await player2.useCard(wanjian, targets2, false);
        }
      }
    },
    ai: {
      order: 9,
      result: { target: 1 }
    }
  }

sp:olchanshuang.code:
{
    audio: 2,
    enable: "phaseUse",
    filterTarget: lib.filter.notMe,
    usable: 1,
    async content(event2, trigger2, player2) {
      const { target: target2 } = event2;
      const choiceList = ["重铸一张牌", "使用一张【杀】", "弃置两张牌"], list = ["重铸", "出杀", "弃牌", "无法选择"];
      let result = [];
      for (let current of [player2, target2]) {
        let list1 = list.slice(), choiceList1 = choiceList.slice();
        list1 = list1.filter((control) => {
          if (control == "无法选择") {
            return false;
          }
          if (control == "重铸") {
            return current.countCards("he", (card2) => current.canRecast(card2));
          }
          if (control == "出杀") {
            return current.countCards("he", (card2) => card2.name == "sha" && current.hasUseTarget(card2));
          }
          if (control == "弃牌") {
            return current.countCards("he", (card2) => lib.filter.cardDiscardable(card2, current)) > 1;
          }
        });
        choiceList1 = choiceList.filter((control) => {
          if (choiceList.indexOf(control) == 0) {
            return current.countCards("he", (card2) => current.canRecast(card2));
          }
          if (choiceList.indexOf(control) == 1) {
            return current.countCards("he", (card2) => card2.name == "sha" && current.hasUseTarget(card2));
          }
          if (choiceList.indexOf(control) == 2) {
            return current.countCards("he", (card2) => lib.filter.cardDiscardable(card2, current)) > 1;
          }
        });
        if (list1.length) {
          if (list1.length == 1) {
            result.push(list.indexOf(list1[0]));
          } else {
            let result1 = await current.chooseControl(list1).set("ai", () => {
              const current2 = _status.event.player;
              const controls = _status.event.controls.slice();
              if (controls.includes("出杀") && current2.countCards("hs", (card2) => card2.name == "sha" && current2.hasValueTarget(card2))) {
                return "出杀";
              }
              if (controls.includes("重铸")) {
                return "重铸";
              }
              return "弃牌";
            }).set("choiceList", choiceList1).forResult();
            if (result1?.control) {
              result.push(list.indexOf(result1.control));
            }
          }
        } else {
          result.push(3);
        }
      }
      player2.popup(list[result[0]]);
      target2.popup(list[result[1]]);
      for (let current of [player2, target2]) {
        if (!current.isIn()) {
          continue;
        }
        switch (list[result[current == player2 ? 0 : 1]]) {
          case "重铸": {
            if (current.countCards("he", (card2) => current.canRecast(card2))) {
              let result2 = await current.chooseCard("he", "请重铸一张牌", (card2, player3) => player3.canRecast(card2), true).forResult();
              if (result2?.bool && result2?.cards?.length) {
                await current.recast(result2.cards);
              }
            }
            break;
          }
          case "出杀": {
            if (current.hasUsableCard("sha")) {
              await current.chooseToUse({
                prompt: "请使用一张【杀】",
                filterCard(card2, player3) {
                  if (card2.name != "sha") {
                    return false;
                  }
                  return lib.filter.filterCard.apply(this, arguments);
                },
                forced: true,
                ai1(card2) {
                  return _status.event.player.getUseValue(card2);
                },
                addCount: false
              });
            }
            break;
          }
          case "弃牌": {
            if (current.countCards("he", (card2) => lib.filter.cardDiscardable(card2, current))) {
              await current.chooseToDiscard("he", 2, true);
            }
            break;
          }
        }
      }
    },
    ai: {
      order(item, player2) {
        return get.order({ name: "sha" }, player2) - 0.1;
      },
      result: {
        target(player2, target2) {
          const att = get.attitude(player2, target2);
          if (target2.countCards("hs", (card2) => {
            return card2.name == "sha" && game.hasPlayer((current) => {
              return target2.canUse(card2, current) && get.effect(current, card2, target2, target2) > 0 && get.effect(current, card2, target2, player2) > 0;
            });
          })) {
            return 3;
          }
          if (att > 0) {
            return 2;
          }
          if (!target2.countCards("h")) {
            return get.sgn(att) + (att == 0 ? 1 : 0);
          }
          return 0;
        }
      }
    },
    group: "olchanshuang_end",
    subSkill: {
      end: {
        audio: "olchanshuang",
        trigger: { player: "phaseJieshuBegin" },
        filter(event2, player2) {
          return player2.hasHistory("lose", (evt) => {
            if (evt.type == "discard") {
              var evtx = evt.getl(player2);
              return evtx && evtx.cards2.length == 2;
            }
            return evt.getParent(2).name == "recast";
          }) || player2.hasHistory("useCard", (evt) => evt.card.name == "sha");
        },
        forced: true,
        locked: false,
        async content(event2, trigger2, player2) {
          let num = 0;
          if (player2.hasHistory("lose", (evt) => evt.getParent(2).name == "recast")) {
            num++;
          }
          if (player2.hasHistory("useCard", (evt) => evt.card.name == "sha")) {
            num++;
          }
          if (player2.hasHistory("lose", (evt) => {
            if (evt.type == "discard") {
              var evtx = evt.getl(player2);
              return evtx && evtx.cards2.length == 2;
            }
          })) {
            num++;
          }
          if (num && player2.countCards("he", (card2) => player2.canRecast(card2))) {
            let result = await player2.chooseCard("he", "请重铸一张牌", (card2, player3) => player3.canRecast(card2), true).forResult();
            if (result?.bool && result?.cards?.length) {
              await player2.recast(result.cards);
            }
          }
          if (num > 1 && player2.countCards("he", (card2) => card2.name == "sha" && player2.hasUseTarget(card2))) {
            await player2.chooseToUse({
              prompt: "请使用一张【杀】",
              filterCard(card2, player3) {
                if (card2.name != "sha") {
                  return false;
                }
                return lib.filter.filterCard.apply(this, arguments);
              },
              forced: true,
              ai1(card2) {
                return _status.event.player.getUseValue(card2);
              }
            });
          }
          if (num > 2 && player2.countCards("he", (card2) => lib.filter.cardDiscardable(card2, player2))) {
            await player2.chooseToDiscard("he", 2, true);
          }
        }
      }
    }
  }

