      player2.removeExtraEquip(skill);
    },
    group: "olzhanjin_guanshi",
    subSkill: {
      guanshi: {
        audio: "olzhanjin",
        nobracket: true,
        equipSkill: true,
        trigger: { player: ["shaMiss", "eventNeutralized"] },
        filter(event2, player2) {
          if (!player2.hasEmptySlot(1) || !lib.card.guanshi || player2.hasSkillTag("unequip_equip1")) {
            return false;
          }
          if (event2.type != "card" || event2.card.name != "sha" || !event2.target.isIn()) {
            return false;
          }
          return player2.countCards("he") >= 2;
        },
        direct: true,
        locked: false,
        async content(event2, trigger2, player2) {
          const next = player2.chooseToDiscard(get.prompt("olzhanjin_guanshi"), "弃置两张牌，令" + get.translation(trigger2.card) + "强制命中", 2, "he").set("ai", function(card2) {
            var evt = _status.event.getTrigger();
            if (get.attitude(evt.player, evt.target) < 0) {
              if (player2.needsToDiscard()) {
                return 15 - get.value(card2);
              }
              if (evt.baseDamage + evt.extraDamage >= Math.min(2, evt.target.hp)) {
                return 8 - get.value(card2);
              }
              return 5 - get.value(card2);
            }
            return -1;
          }).set("complexCard", true);
          next.logSkill = "olzhanjin_guanshi";
          const result = await next.forResult();
          if (result.bool) {
            if (event2.triggername == "shaMiss") {
              trigger2.untrigger();
              trigger2.trigger("shaHit");
              trigger2._result.bool = false;
              trigger2._result.result = null;
            } else {
              trigger2.unneutralize();
            }
          }
        },
        mod: {
          attackRangeBase(player2) {
            var num = lib.card?.guanshi?.distance?.attackFrom;
            if (typeof num != "number" || !player2.hasEmptySlot(1)) {
              return;
            }
            return Math.max(player2.getEquipRange(player2.getCards("e")), 1 - num);
          }
        },
        ai: {
          directHit_ai: true,
          skillTagFilter(player2, tag, arg) {
            if (player2._olzhanjin_guanshi_temp || !player2.hasEmptySlot(1) || !lib.card.guanshi || player2.hasSkillTag("unequip_equip1")) {
              return;
            }
            player2._olzhanjin_guanshi_temp = true;
            var bool = get.attitude(player2, arg.target) < 0 && arg.card && arg.card.name == "sha" && player2.countCards("he", (card2) => {
              return card2 != arg.card && (!arg.card.cards || !arg.card.cards.includes(card2)) && get.value(card2) < 5;
            }) > 1;
            delete player2._olzhanjin_guanshi_temp;
            return bool;
          },
          effect: {
            target(card2, player2, target2) {
              if (player2.hasSkillTag("unequip_equip1")) {
                return;
              }
              if (player2 == target2 && get.subtype(card2) == "equip1") {
                if (get.equipValue(card2) <= get.equipValue({ name: "guanshi" })) {
                  return 0;
                }
              }
            }
          }
        }
      }
    }
  }

