sp:olgongjie.code:
{
    audio: 2,
    trigger: { global: "phaseBegin" },
    filter(event2, player2) {
      if (!player2.countCards("he")) {
        return false;
      }
      let history = player2.actionHistory, isRound = false;
      history.forEach((evt, index) => {
        if (evt.isRound) {
          isRound = index;
        }
      });
      if (isRound === false) {
        return false;
      }
      for (let num = 0; num < history.length - 1; num++) {
        if (num < isRound || history[num].isSkipped) {
          continue;
        }
        return num == history.length - 1;
      }
      return true;
    },
    direct: true,
    async content(event2, trigger2, player2) {
      var num = player2.countCards("he"), draws = [];
      var { bool, targets: targets2 } = await player2.chooseTarget(get.prompt2("olgongjie"), [1, num], lib.filter.notMe).set("ai", (target3) => get.attitude(_status.event.player, target3)).forResult();
      if (!bool) {
        return;
      }
      targets2 = targets2.sortBySeat();
      player2.logSkill("olgongjie", targets2);
      for (var target2 of targets2) {
