sp:ollangdao.code:
{
    audio: 2,
    trigger: { player: "useCardToPlayer" },
    filter(event2, player2) {
      if (event2.card.name != "sha") {
        return false;
      }
      return event2.isFirstTarget && event2.targets.length == 1 && player2.getStorage("ollangdao").length < 3;
    },
    logTarget: "target",
    onremove: true,
    check(event2, player2) {
      if (get.attitude(player2, event2.target) > 0) {
        if (player2.getStorage("ollangdao").includes(1) && game.hasPlayer((current) => {
          return player2.canUse(event2.card, current) && get.effect(current, event2.card, player2, player2) > 0;
        })) {
          return event2.getRand() < 0.5;
        }
        return false;
      }
      return event2.target.getHp() <= 2 || player2.getDamagedHp() > 1 || !player2.hasCard({ color: "black" }, "hes");
    },
    async content(event2, trigger2, player2) {
      var result = event2.result;
      var target2 = trigger2.target;
      var send = function(card3, list2) {
        var next2 = game.createEvent("ollangdao_choose", false);
        next2.setContent(lib.skill.ollangdao.contentx);
        next2.set("card", card3);
        next2.set("list", list2);
        game.resume();
      };
      var sendback = function(result2, player3) {
        if (!result2) {
          result2 = {};
        }
        if (typeof result2.index !== "number" || result2.index < 0) {
          result2.index = [0, 1, 2].find((i2) => !event2.player.getStorage("ollangdao").includes(i2));
        }
        results.push([player3, result2]);
      };
      var ai_targets = [];
      var results = [];
      var players = [player2, target2];
      var withme = false, withol = false, withai = false;
      for (var i = 0; i < players.length; i++) {
        if (_status.connectMode) {
          players[i].showTimer();
        }
        const card3 = trigger2.card, list2 = player2.getStorage("ollangdao");
        if (players[i].isOnline()) {
          withol = true;
          players[i].send(send, card3, list2);
          players[i].wait(sendback);
        } else if (players[i] == game.me) {
          withme = true;
          var next = game.createEvent("ollangdao_choose", false);
          next.setContent(lib.skill.ollangdao.contentx);
          next.set("card", card3);
          next.set("list", list2);
          if (_status.connectMode) {
            game.me.wait(sendback);
          }
        } else {
          ai_targets.push(players[i]);
        }
      }
      if (ai_targets.length) {
        for (var i = 0; i < ai_targets.length; i++) {
          if (players.includes(ai_targets[i])) {
            var target2 = ai_targets[i];
            var list = [0, 1, 2].removeArray(player2.getStorage("ollangdao"));
            var index = list[0];
            if (get.attitude(target2, player2) < 0) {
              if (!game.hasPlayer((current) => {
                return !trigger2.targets.includes(current) && player2.canUse(trigger2.card, current) && get.effect(current, trigger2.card, player2, target2) < 0;
              })) {
                list.removeArray([0, 2]);
              }
              if (player2.getStorage("ollangdao").includes(2)) {
                list.remove(0);
              }
            } else {
              if (!game.hasPlayer((current) => {
                return !trigger2.targets.includes(current) && player2.canUse(trigger2.card, current) && get.effect(current, trigger2.card, player2, target2) > 0;
              })) {
                list.remove(1);
              }
              if (!list.includes(1)) {
                list.remove(0);
              }
            }
            if (list.length) {
              index = list.randomGet();
            }
            sendback({ index }, target2);
            ai_targets.splice(i--, 1);
          }
        }
        if (ai_targets.length) {
          ai_targets.randomSort();
          setTimeout(function() {
            event2.interval = setInterval(
