              return get.damageEffect(target2, player3, player3);
            }).forResult();
          }
          if (result.bool) {
            const target2 = result.targets[0];
            player2.addTempSkill("olfushi_buff3");
            player2.initStorage("olfushi_buff3", []);
            player2.getStorage("olfushi_buff3").push([target2, trigger2.card]);
          }
        }
      },
      buff2: {
        charlotte: true,
        onremove: true,
        trigger: { source: "damageBegin2" },
        filter(event2, player2) {
          return event2.card && player2.getStorage("olfushi_buff2").some((info) => info[0] == event2.player && info[1] == event2.card);
        },
