    filter(event2, player2) {
      return game.getGlobalHistory(
        "everything",
        (evt) => {
          return evt.name == "damage" && evt.player == player2;
        },
        event2
      ).indexOf(event2) == 0;
    },
    checkx(event2, player2) {
      var target2 = event2.source;
      return get.damageEffect(player2, target2, player2) <= 0;
    },
    forced: true,
    async content(event2, trigger2, player2) {
      const cards2 = get.bottomCards(3, true);
      const result = await player2.chooseButton(["###藏心：请选择要弃置的牌###若以此法弃置了红桃牌，则减少弃置红桃牌数的伤害", cards2], [0, cards2.length], true, "allowChooseAll").set("ai", function(button) {
        if (!_status.event.bool && get.suit(button.link, false) == "heart") {
          return 0;
        }
        if (get.suit(button.link, false) != "heart") {
          return 1;
        }
        const num = get.event().getTrigger().num;
        if (num > ui.selected.buttons.filter((but) => get.suit(but.link, false) == "heart").length) {
          return 1;
        }
        return 0;
      }).set("bool", lib.skill.olcangxin.checkx(trigger2, player2)).forResult();
      if (result.bool) {
        player2.$throw(result.links, 1e3);
        await game.cardsDiscard(result.links);
        const num = result.links.filter((card2) => get.suit(card2, false) == "heart").length;
        if (num) {
          trigger2.num -= Math.min(trigger2.num, num);
        }
      } else {
        event2.finish();
        return;
      }
      await game.delayx();
    },
    group: "olcangxin_yingzi",
    subSkill: {
