        return _status.event.choice;
      }).set(
        "choice",
        (function() {
          var info2 = lib.skill.olgangshu.getInfo(player2);
          if (info2[1] == 0) {
            return 1;
          }
          if (info2[2] < 5 && player2.hasCard((card2) => {
            return get.name(card2) == "sha" && player2.hasValueTarget(card2);
          }, "hs") && !player2.getCardUsable("sha")) {
