      const str = `请交给其一张牌${forced ? "" : "或点击“取消”令其回复1点体力"}。`;
      const bool = !target2.countCards(position) ? false : (await target2.chooseToGive(player2, `${get.translation(player2)}对你发动了【款塞】`, str, position, forced).set("ai", (card2) => {
