          player3.popup(group + "2", get.groupnature(group, "raw"));
        }
      };
      const next = game.createEvent("olgoude_" + result.control);
      next.player = player2;
      next.setContent(contents[result.control]);
    },
    ai: {
      threaten: 3,
      effect: {
        player_use(card2, player2, target2) {
          if (typeof card2 == "object" && card2.cards && card2.cards.some((card3) => {
            return get.position(card3) == "h";
          }) && !get.tag(card2, "draw") && !get.tag(card2, "gain") && !get.tag(card2, "discard") && player2 == _status.currentPhase && player2.needsToDiscard() == 1 && game.countPlayer((current) => {
