      return game.hasPlayer((current) => {
        return [true, false].some((bool) => !player2.getStorage("olzhuyan_" + bool).includes(current) && lib.skill.olzhuyan.getNum(current, bool));
      });
    },
    getNum(player2, status) {
      if (!_status.olzhuyan || !_status.olzhuyan[player2.playerid]) {
        return 0;
      }
      let num = _status.olzhuyan[player2.playerid][status ? 1 : 0];
      if (status) {
        let no = num > 5;
        num -= player2.countCards("h");
        if (no) {
          num = Math.min(0, num);
        }
      } else {
        num -= player2.hp;
        if (num + player2.hp < 1) {
          num = 1 - player2.hp;
        }
      }
      return num;
    },
    getMap(player2) {
      const map = {};
      for (const bool of [true, false]) {
        const targeted = player2.getStorage("olzhuyan_" + bool);
        game.countPlayer((current) => {
          if (targeted.includes(current)) {
            return false;
          }
          if (!map[current.playerid]) {
            map[current.playerid] = [];
          }
          map[current.playerid][bool ? 1 : 0] = lib.skill.olzhuyan.getNum(current, bool);
        });
      }
