    async cost(event2, trigger2, player2) {
      const map = get.info(event2.skill).getMap(player2);
      const targetprompt = (map2, target2) => {
        const list = map2[target2.playerid] || [];
        let str = "";
        for (let i = 0; i < 2; i++) {
          if (list[i] === void 0) {
            str += "--";
          } else {
            str += (list[i] > 0 ? "+" : "") + list[i];
          }
          str += "/";
        }
        return str.slice(0, -1);
      };
      const func = (targetprompt2, map2) => {
        game.countPlayer((target2) => {
          let text = targetprompt2(map2, target2);
