        result = await player2.chooseControl(choices).set("choiceList", ["令" + get.translation(target2) + (list[0] > 0 ? "回复" : "失去") + Math.abs(list[0]) + "点体力" + (list[0] < 0 ? "（至多失去至1）" : ""), "令" + get.translation(target2) + (list[1] > 0 ? "摸" : "弃置") + get.cnNumber(Math.abs(list[1])) + "张" + (list[1] > 0 ? "" : "手") + "牌" + (list[1] > 0 ? "（至多摸至5）" : "")]).set("prompt", "驻颜：请选择一项").set("ai", () => _status.event.choice).set(
          "choice",
          (() => {
            const v1 = list[0], v2 = get.sgn(list[1]) * Math.sqrt(Math.abs(list[1]));
            if (get.attitude(player2, target2) > 0) {
              return v1 > v2 ? 0 : 1;
            }
            return v1 > v2 ? 1 : 0;
          })()
        ).forResult();
      } else {
