sp:olhuiyun.code:
{
    audio: 2,
    enable: "phaseUse",
    viewAs: {
      name: "huogong",
      storage: { olhuiyun: true }
    },
    filterCard: true,
    position: "hes",
    onuse(links, player2) {
      player2.addTempSkill("olhuiyun_after");
      player2.addTempSkill("olhuiyun_record");
    },
    ai: {
      effect: {
        player(card2, player2, target2) {
          if (get.attitude(player2, target2) > 0 && card2?.name === "huogong" && card2.storage?.olhuiyun && player2.getStorage("olhuiyun_used").length < 3) {
            return [0, 0.5, 0, 0.5];
          }
        }
      }
    },
    subSkill: {
      used: {
        charlotte: true,
        onremove: true
      },
      after: {
        audio: "olhuiyun",
        trigger: { global: "useCardAfter" },
        charlotte: true,
        locked: true,
        filter(event2, player2) {
          if (player2.getStorage("olhuiyun_used").length > 2) {
            return false;
          }
          return event2.card.name == "huogong" && event2.card.storage?.olhuiyun && event2.targets.some((i) => i.isIn());
        },
        async cost(event2, trigger2, player2) {
          const choices = [];
          const choiceList = ["使用展示牌，然后重铸所有手牌", "使用一张手牌，然后重铸展示牌", "摸一张牌"];
          for (let i = 1; i <= 3; i++) {
            if (!player2.getStorage("olhuiyun_used").includes(i)) {
              choices.push("选项" + get.cnNumber(i, true));
            } else {
              choiceList[i - 1] = '<span style="opacity:0.5">' + choiceList[i - 1] + "</span>";
            }
          }
          const { control } = await player2.chooseControl(choices).set("choiceList", choiceList).set("prompt", "晖云：选择一项，令" + get.translation(trigger2.targets) + "可以选择执行").set("ai", () => {
            return get.event().choice;
          }).set(
            "choice",
            (() => {
              if (choices.length == 1) {
                return choices[0];
              }
              const choicesx = choices.slice();
              if (get.attitude(player2, trigger2.targets[0]) > 0 && choices.includes("选项三")) {
                return "选项三";
              }
              choicesx.remove("选项三");
              return choicesx.randomGet();
            })()
          ).forResult();
          event2.result = {
            bool: true,
            cost_data: control
          };
        },
        async content(event2, trigger2, player2) {
          const index = ["选项一", "选项二", "选项三"].indexOf(event2.cost_data) + 1;
          game.log(player2, "选择了", "#y" + event2.cost_data);
          player2.addTempSkill("olhuiyun_used", "roundStart");
          player2.markAuto("olhuiyun_used", [index]);
          for (const target2 of trigger2.targets.sortBySeat()) {
            if (!target2.isIn()) {
              continue;
            }
            const cards2 = target2.getCards("h", (card2) => card2.hasGaintag("olhuiyun_tag"));
            if (index == 1 && cards2.length) {
              const result = await target2.chooseToUse({
                filterCard(card2) {
                  if (get.itemtype(card2) != "card" || !card2.hasGaintag("olhuiyun_tag")) {
                    return false;
                  }
                  return lib.filter.filterCard.apply(this, arguments);
                },
                prompt: "是否使用一张展示牌，然后重铸所有手牌？",
                addCount: false
              }).forResult();
              if (result.bool) {
                const hs = target2.getCards("h", lib.filter.cardRecastable);
                if (hs.length) {
                  await target2.recast(hs);
                }
              }
            } else if (index == 2) {
              const result = await target2.chooseToUse({
                filterCard(card2) {
                  if (get.itemtype(card2) != "card" || get.position(card2) != "h" && get.position(card2) != "s") {
                    return false;
                  }
                  return lib.filter.filterCard.apply(this, arguments);
                },
                prompt: "是否使用一张手牌，然后重铸展示牌？",
                addCount: false
              }).forResult();
              if (result.bool) {
                const hs = target2.getCards("h", (card2) => {
                  if (!card2.hasGaintag("olhuiyun_tag")) {
                    return false;
                  }
                  return target2.canRecast(card2);
                });
                if (hs.length) {
                  await target2.recast(hs);
                }
              }
            } else if (index == 3) {
              const { bool } = await target2.chooseBool("是否摸一张牌？").set("ai", () => true).forResult();
              if (bool) {
                await target2.draw();
              }
            }
          }
        }
      },
      record: {
        trigger: { global: "showCardsEnd" },
        forced: true,
        charlotte: true,
        popup: false,
        firstDo: true,
        filter(event2, player2) {
          if (event2.getParent().name != "huogong") {
            return false;
          }
          const card2 = event2.getParent(2).card;
          return card2?.storage?.olhuiyun;
        },
        content() {
          game.broadcastAll((cards2) => {
            cards2.forEach((card2) => card2.addGaintag("olhuiyun_tag"));
          }, trigger.cards);
        }
      }
    }
  }

