        target(player2, target2, card2, isLink) {
          let eff = -1.5, odds = 1.35, num = 1;
          if (isLink) {
            let cache = _status.event.getTempCache("sha_result", "eff");
            if (typeof cache !== "object" || cache.card !== get.translation(card2)) {
              return eff;
            }
