              player: player2,
              card: card2,
              jiu: true
            })) {
              eff = -0.5;
            } else {
              num = 2;
              if (get.attitude(player2, target2) > 0) {
                eff = -7;
              } else {
                eff = -4;
              }
            }
          }
          if (!player2.hasSkillTag(
