              range = [1, 1];
            } else if (typeof select === "number") {
              range = [select, select];
            } else if (get.itemtype(select) === "select") {
              range = select;
            } else if (typeof select === "function") {
              range = select(card2, player2);
              if (typeof range == "number") {
                range = [range, range];
              }
            }
            if (info.singleCard) {
              range = [1, 1];
            }
            game.checkMod(card2, player2, range, "selectTarget", player2);
