            return target2.countCards("he", (card2) => 4 - get.value(card2)) ? 1 : -1;
          }
          return (target2.countCards("he") - 2) / 3;
        }
      }
    },
    subSkill: {
      replace: {
        trigger: { global: "phaseJieshuBegin" },
        filter(event2, player2) {
          return event2.player.hasCard((card2) => card2.hasGaintag("olzhubi_tag"), "h");
        },
        forced: true,
        locked: false,
        logTarget: "player",
        async content(event2, trigger2, player2) {
          const cards2 = get.bottomCards(5, true);
          await game.cardsGotoOrdering(cards2);
          const {
            targets: [target2]
          } = event2;
          const hs = target2.getCards("h", (card2) => card2.hasGaintag("olzhubi_tag"));
          const result = await target2.chooseToMove("铸币：用任意“币”交换牌堆底等量张牌").set("filterMove", function(from, to) {
            return typeof to != "number";
