          ]).set("processAI", function(list) {
            var all = list[0][1].concat(list[1][1]), cards3 = all.slice(0);
            var num = _status.event.num;
            cards3.sort(function(a, b) {
              return get.value(b) - get.value(a);
            });
            return [cards3.slice(num), cards3.slice(0, num)];
          }).set("num", hs.length).forResult();
          if (result.bool) {
            event2.forceDie = true;
            const cards22 = result.moved[0];
            const lose = [], gain = cards2.slice();
            for (const i of cards22) {
              if (hs.includes(i)) {
                lose.push(i);
              } else {
                gain.remove(i);
              }
            }
