    },
    check(card2) {
      var player2 = _status.event.player;
      if (player2.hasValueTarget(card2)) {
        return 10 - get.value(card2);
      }
      return 0.1;
    },
    async content(event2, trigger2, player2) {
      const { target: target2, cards: cards2 } = event2;
      let result;
      if (target2.countCards("h", (card2) => {
        return get.type(card2) == "basic" && lib.filter.cardDiscardable(card2, target2, "olxiaosi");
      }) == 0) {
        event2.draw = true;
        result = event2._result;
      } else {
        result = await target2.chooseToDiscard("h", true, "效死：弃置一张基本牌", { type: "basic" }).forResult();
      }
      let cards22 = cards2.slice(0);
      if (result.bool) {
        cards22 = cards22.addArray(result.cards);
      }
      event2.cards2 = cards22;
      while (true) {
        const cardsx = event2.cards2.filter((i) => get.position(i, true) == "d" && player2.hasUseTarget(i, false));
        if (!cardsx.length) {
          break;
        }
        const result2 = await player2.chooseButton(["效死：是否使用其中的一张牌？", cardsx]).set("filterButton", (button) => {
          return _status.event.player.hasUseTarget(button.link, false);
        }).set("ai", (button) => {
          if (button.link.name == "jiu") {
            return 10;
          }
          return _status.event.player.getUseValue(button.link);
        }).forResult();
        if (result2.bool) {
          const card2 = result2.links[0];
          event2.cards2.remove(card2);
          player2.$gain2(card2, false);
          await game.delayx();
          await player2.chooseUseTarget(true, card2, false, "nodistance");
        } else {
          break;
        }
        if (!event2.cards2.filter((i) => get.position(i, true) == "d" && player2.hasUseTarget(i, false)).length) {
          break;
        }
      }
      if (event2.draw) {
        await player2.draw();
      }
    },
    ai: {
      order: 4.5,
      result: {
        player: 1,
        target: -1
      }
    }
  }

