            if (typeof map[id].extraDamage == "number") {
              num += map[id].extraDamage;
            }
          }
          if (target2.hasSkillTag("filterDamage", null, {
            player: trigger2.player,
            card: trigger2.card
          })) {
            num = 1;
          }
          return num;
