sp:olzeyue.code:
{
    audio: 2,
    trigger: { player: "phaseZhunbeiBegin" },
    limited: true,
    skillAnimation: true,
    animationColor: "water",
    direct: true,
    filter(event2, player2) {
      var sources = [], history = player2.actionHistory;
      for (var i = history.length - 1; i >= 0; i--) {
        if (i < history.length - 1 && history[i].isMe) {
          break;
        }
        for (var evt of history[i].damage) {
          if (evt.source && evt.source != player2 && evt.source.isIn()) {
            sources.add(evt.source);
          }
        }
      }
      for (var source of sources) {
        var skills2 = source.getStockSkills("一！", "五！");
        for (var skill of skills2) {
          var info = get.info(skill);
          if (info && !info.persevereSkill && !info.charlotte && !get.is.locked(skill, source) && source.hasSkill(skill, null, null, false)) {
            return true;
          }
        }
      }
      return false;
    },
    async content(event2, trigger2, player2) {
      let sources = [], history = player2.actionHistory;
      for (let i = history.length - 1; i >= 0; i--) {
        if (i < history.length - 1 && history[i].isMe) {
          break;
        }
        for (const evt of history[i].damage) {
          if (evt.source && evt.source != player2 && evt.source.isIn()) {
            sources.add(evt.source);
          }
        }
      }
      sources = sources.filter(function(source) {
        var skills2 = source.getStockSkills("一！", "五！");
        for (var skill of skills2) {
          var info = get.info(skill);
          if (info && !info.persevereSkill && !info.charlotte && !get.is.locked(skill, source) && source.hasSkill(skill, null, null, false)) {
            return true;
          }
        }
        return false;
      });
      const result = await player2.chooseTarget(get.prompt("olzeyue"), "令一名可选角色的一个非锁定技失效", function(card2, player3, target2) {
        return _status.event.sources.includes(target2);
      }).set("sources", sources).set("ai", function(target2) {
        var player3 = _status.event.player, att = get.attitude(player3, target2);
        if (att >= 0) {
          return 0;
        }
        return get.threaten(target2, player3);
      }).forResult();
      if (result.bool) {
        const target2 = result.targets[0];
        player2.logSkill("olzeyue", target2);
        player2.awakenSkill(event2.name);
        event2.target = target2;
        let skills2 = target2.getStockSkills("一！", "五！");
        skills2 = skills2.filter(function(skill2) {
          var info = get.info(skill2);
          if (info && !info.charlotte && !get.is.locked(skill2, target2) && target2.hasSkill(skill2, null, null, false)) {
            return true;
          }
        });
        let result2;
        if (skills2.length == 1) {
          event2._result = { control: skills2[0] };
        } else {
          result2 = await player2.chooseControl(skills2).set("prompt", "令" + get.translation(target2) + "的一个技能失效").forResult();
        }
        const skill = skills2.length == 1 ? event2._result.control : result2.control;
        target2.disableSkill("olzeyue_" + player2.playerid, skill);
        target2.storage["olzeyue_" + player2.playerid] = true;
        player2.addSkill("olzeyue_round");
        player2.markAuto("olzeyue_round", [target2]);
        if (!player2.storage.olzeyue_map) {
          player2.storage.olzeyue_map = {};
        }
        player2.storage.olzeyue_map[target2.playerid] = 0;
        game.log(target2, "的技能", "#g【" + get.translation(skill) + "】", "被失效了");
      } else {
        event2.finish();
        return;
      }
    },
    ai: { threaten: 3 },
    subSkill: {
      round: {
        charlotte: true,
        trigger: { global: "roundEnd" },
        filter(event2, player2) {
          var storage = player2.getStorage("olzeyue_round");
          for (var source of storage) {
            if (source.isIn() && source.canUse("sha", player2, false)) {
              return true;
            }
          }
          return false;
        },
        forced: true,
        popup: false,
        async content(event2, trigger2, player2) {
          event2.targets = player2.storage.olzeyue_round.slice(0).sortBySeat();
          event2.target = event2.targets.shift();
          event2.forceDie = true;
          while (true) {
            const target2 = event2.target;
            const map = player2.storage.olzeyue_map;
            if (target2.storage["olzeyue_" + player2.playerid]) {
              map[target2.playerid]++;
            }
            event2.num = map[target2.playerid] - 1;
            if (event2.num <= 0) {
              event2.finish();
              return;
            }
            while (true) {
              event2.num--;
              await target2.useCard(player2, { name: "sha", isCard: true }, false, "olzeyue_round");
              const key = "olzeyue_" + player2.playerid;
              if (target2.storage[key] && player2.hasHistory("damage", function(evt) {
                return evt.card.name == "sha" && evt.getParent().type == "card" && evt.getParent(3) == event2;
              })) {
                for (const skill in target2.disabledSkills) {
                  if (target2.disabledSkills[skill].includes(key)) {
                    game.log(target2, "恢复了技能", "#g【" + get.translation(skill) + "】");
                  }
                }
                delete target2.storage[key];
                target2.enableSkill(key);
              }
              if (event2.num > 0 && player2.isIn() && target2.isIn() && target2.canUse("sha", player2, false)) {
                continue;
              } else if (event2.targets.length > 0) {
                event2.target = event2.targets.shift();
                break;
              } else {
                return;
              }
            }
          }
        }
      }
    }
  }

