sp:yilie.code:
{
    audio: 2,
    enable: "chooseToUse",
    hiddenCard(player2, name) {
      if (get.type(name) == "basic" && lib.inpile.includes(name) && !player2.getStorage("yilie_count").includes(name)) {
        var hs = player2.getCards("hs");
        if (hs.length < 2) {
          return false;
        }
        var bool = false, map = {};
        for (var card2 of hs) {
          var color = get.color(card2);
          if (!map[color]) {
            map[color] = true;
          } else {
            bool = true;
            break;
          }
        }
        return bool;
      }
    },
    filter(event2, player2) {
      if (event2.type == "wuxie") {
        return false;
      }
      var list = player2.getStorage("yilie_count");
      var hs = player2.getCards("hs");
      if (hs.length < 2) {
        return false;
      }
      var bool = false, map = {};
      for (var card2 of hs) {
        var color = get.color(card2);
        if (!map[color]) {
          map[color] = true;
        } else {
          bool = true;
          break;
        }
      }
      if (!bool) {
        return false;
      }
      for (var name of lib.inpile) {
        if (get.type(name) != "basic" || list.includes(name)) {
          continue;
        }
        var card2 = { name };
        if (event2.filterCard(get.autoViewAs(card2, "unsure"), player2, event2)) {
          return true;
        }
        if (name == "sha") {
          for (var nature of lib.inpile_nature) {
            card2.nature = nature;
            if (event2.filterCard(get.autoViewAs(card2, "unsure"), player2, event2)) {
              return true;
            }
          }
        }
      }
      return false;
    },
    chooseButton: {
      dialog(event2, player2) {
        var list = [];
        var storage = player2.getStorage("yilie_count");
        for (var i of lib.inpile) {
          if (get.type(i) != "basic" || storage.includes(i)) {
            continue;
          }
          var card2 = { name: i };
          if (event2.filterCard(get.autoViewAs(card2, "unsure"), player2, event2)) {
            list.push(["基本", "", i]);
          }
          if (i == "sha") {
            for (var j of lib.inpile_nature) {
              card2.nature = j;
              if (event2.filterCard(get.autoViewAs(card2, "unsure"), player2, event2)) {
                list.push(["基本", "", i, j]);
              }
            }
          }
        }
        return ui.create.dialog("义烈", [list, "vcard"], "hidden");
      },
      check(button) {
        var player2 = _status.event.player;
        var evt = _status.event.getParent();
        var name = button.link[2], card2 = { name, nature: button.link[3] };
        if (name == "shan") {
          return 2;
        }
        if (evt.type == "dying") {
          if (get.attitude(player2, evt.dying) < 2) {
            return 0;
          }
          if (name == "jiu") {
            return 2.1;
          }
          return 1.9;
        }
        if (evt.type == "phase") {
          if (button.link[2] == "jiu") {
            if (player2.getUseValue({ name: "jiu" }) <= 0) {
              return 0;
            }
            var cards2 = player2.getCards("hs", (cardx) => get.value(cardx) < 8);
            cards2.sort((a, b) => get.value(a) - get.value(b));
            if (cards2.some((cardx) => get.name(cardx) == "sha" && !cards2.slice(0, 2).includes(cardx))) {
              return player2.getUseValue({ name: "jiu" });
            }
            return 0;
          }
          return player2.getUseValue(card2) / 4;
        }
        return 1;
      },
      backup(links, player2) {
        return {
          audio: "yilie",
          selectCard: 2,
          filterCard(card2, player3) {
            var color = get.color(card2);
            if (ui.selected.cards.length) {
              return color == get.color(ui.selected.cards[0]);
            }
            return player3.hasCard(function(cardx) {
              return card2 != cardx && get.color(cardx) == color;
            }, "hs");
          },
          position: "hs",
          complexCard: true,
          check: (card2) => 8 - get.value(card2),
          popname: true,
          viewAs: {
            name: links[0][2],
            nature: links[0][3]
          },
          async precontent(event2, trigger2, player3) {
