        return false;
      }
      if (event2.card.name != "sha" && get.type(event2.card) != "trick") {
        return false;
      }
      const [left, right, left2, right2] = get.info("saodi").getTargets(player2, target2);
      return target2 == left2 && left.some((i) => lib.filter.targetEnabled2(event2.card, player2, i)) || target2 == right2 && right.some((i) => lib.filter.targetEnabled2(event2.card, player2, i));
    },
    getTargets(source, target2) {
      let left = [], right = [], left2 = source, right2 = source;
      while (left2 != target2 && right2 != target2) {
        left2 = left2.getPrevious();
        right2 = right2.getNext();
        if (left2 != target2) {
          left.push(left2);
        }
        if (right2 != target2) {
          right.push(right2);
        }
      }
      return [left, right, left2, right2];
    },
    aiJudge(card2, player2, target2, bool) {
      let left3 = false, right3 = false;
      let eff_left = 0, eff_right = 0;
      const [left, right, left2, right2] = get.info("saodi").getTargets(player2, target2);
      if (target2 == left2) {
        for (const i of left) {
          if (lib.filter.targetEnabled2(card2, player2, i)) {
            left3 = true;
            eff_left += get.effect(i, card2, player2, player2);
          }
        }
      }
      if (target2 == right2) {
        for (const i of right) {
          if (lib.filter.targetEnabled2(card2, player2, i)) {
            right3 = true;
            eff_right += get.effect(i, card2, player2, player2);
          }
        }
      }
      if (left3 && right3) {
        if (!bool) {
          return Math.max(eff_left, eff_right);
        }
        if (eff_left > Math.max(0, eff_right)) {
          return "↖顺时针";
        }
        if (eff_right > Math.max(0, eff_left)) {
          return "逆时针↗";
        }
        return "cancel2";
      } else if (left3) {
        if (bool) {
          return eff_left > 0 ? "↖顺时针" : "cancel2";
        }
        return eff_left;
      } else if (right3) {
        if (bool) {
          return eff_right > 0 ? "逆时针↗" : "cancel2";
        }
        return eff_right;
      } else {
        return bool ? "cancel2" : 0;
      }
    },
    async cost(event2, trigger2, player2) {
      const choices = [];
      const { skill } = event2, { target: target2, card: card2 } = trigger2;
      const [left, right, left2, right2] = get.info(skill).getTargets(player2, target2);
      if (target2 == left2 && left.some((i) => lib.filter.targetEnabled2(card2, player2, i))) {
        choices.push("↖顺时针");
      }
      if (target2 == right2 && right.some((i) => lib.filter.targetEnabled2(card2, player2, i))) {
        choices.push("逆时针↗");
      }
      choices.push("cancel2");
      const { control } = await player2.chooseControl(choices).set("prompt", get.prompt(skill)).set("prompt2", `令自己和${get.translation(target2)}某个方向之间的所有角色均成为${get.translation(card2)}的目标`).set("choices", choices).set("ai", () => {
        const evt = get.event().getTrigger();
        return lib.skill.saodi.aiJudge(evt.card, evt.player, evt.target, true);
      }).forResult();
      if (control === "cancel2") {
        return;
      }
      const targets2 = [];
      game.log(player2, "选择了", "#g" + control);
      if (control == "↖顺时针") {
        var current = player2.getPrevious();
        while (current != target2) {
          if (lib.filter.targetEnabled2(card2, player2, current)) {
            targets2.push(current);
          }
          current = current.getPrevious();
        }
      } else {
        var current = player2.getNext();
        while (current != target2) {
          if (lib.filter.targetEnabled2(card2, player2, current)) {
            targets2.push(current);
          }
          current = current.getNext();
        }
      }
      event2.result = {
        bool: true,
        targets: targets2
      };
    },
    async content(event2, trigger2, player2) {
      if (!event2.isMine() && !event2.isOnline()) {
        await game.delayx();
      }
      trigger2.targets.addArray(event2.targets);
    },
    ai: {
      effect: {
        player_use(card2, player2, target2) {
          if (!target2 || player2._saodi_judging || ui.selected.targets.length || player2 == target2 || target2.hasSkill("undist")) {
            return;
          }
          if (typeof card2 != "object" || card2.name != "sha" && get.type(card2) != "trick") {
            return false;
          }
          player2._saodi_judging = true;
          var effect = lib.skill.saodi.aiJudge(card2, player2, target2);
          delete player2._saodi_judging;
          if (effect > 0) {
            return [1, effect / Math.max(0.01, get.attitude(player2, player2))];
          }
        }
      }
    }
  }

