sp:oljuanxia.code:
{
    audio: 2,
    trigger: { player: "phaseJieshuBegin" },
    direct: true,
    async content(event2, trigger2, player2) {
      const result = await player2.chooseTarget(get.prompt2("oljuanxia"), lib.filter.notMe).set("ai", function(target2) {
        const player3 = _status.event.player, list2 = [];
        for (const name of lib.inpile) {
          const info = lib.card[name];
          if (!info || info.type != "trick" || info.notarget || info.selectTarget && info.selectTarget != 1) {
            continue;
          }
          if (!player3.canUse(name, target2, false)) {
            continue;
          }
          const eff = get.effect(target2, { name }, player3, player3);
          if (eff > 0) {
            list2.push(eff);
          }
        }
        list2.sort().reverse();
        if (!list2.length) {
          return 0;
        }
        return list2[0] + (list2[1] || 0) + (list2[2] || 0);
      }).forResult();
      if (result.bool) {
        const target2 = result.targets[0];
        event2.target = target2;
        player2.logSkill("oljuanxia", target2);
      } else {
        event2.finish();
        return;
      }
      let list = [];
      for (const name of lib.inpile) {
        const info = lib.card[name];
        if (!info || info.type != "trick" || info.notarget || info.selectTarget && info.selectTarget != 1) {
          continue;
        }
        list.push(name);
      }
      if (!list.length) {
        event2.finish();
        return;
      } else {
        event2.list = list;
        event2.count = 0;
      }
      while (true) {
        list = event2.list.filter(function(name) {
          return player2.canUse(name, event2.target, false);
        });
        if (list.length) {
          const next = player2.chooseButton(["视为对" + get.translation(event2.target) + "使用一张牌", [list, "vcard"]]).set("ai", function(button) {
            let evt = _status.event.getParent(), eff = get.effect(evt.target, { name: button.link[2] }, evt.player, evt.player);
            if (evt.target.hp < 2 || get.attitude(evt.player, evt.target) > 0 || evt.target.hp < 3 && get.tag(button.link, "damage")) {
              return eff;
            }
            return eff + get.effect(evt.player, { name: "sha" }, evt.target, evt.player);
          });
          if (event2.count == 0) {
            next.set("forced", true);
          }
          const result2 = await next.forResult();
          if (result2.bool) {
            event2.count++;
            const name = result2.links[0][2];
            event2.list.remove(name);
            await player2.useCard({ name, isCard: true }, event2.target, false);
          } else {
            event2.stopped = true;
          }
        } else {
          event2.stopped = true;
        }
        if (event2.target.isIn() && event2.count > 0) {
          if (event2.count < 3 && !event2.stopped && event2.list.length > 0) {
            continue;
          } else {
            event2.target.addTempSkill("oljuanxia_counter", { player: "phaseAfter" });
            if (!event2.target.storage.oljuanxia_counter) {
              event2.target.storage.oljuanxia_counter = {};
            }
            if (!event2.target.storage.oljuanxia_counter[player2.playerid]) {
              event2.target.storage.oljuanxia_counter[player2.playerid] = 0;
            }
            event2.target.storage.oljuanxia_counter[player2.playerid] += event2.count;
          }
        }
        break;
      }
    },
    subSkill: {
      counter: {
        trigger: { player: "phaseEnd" },
        forced: true,
        charlotte: true,
        onremove: true,
        filter(event2, player2) {
          var map1 = _status.connectMode ? lib.playerOL : game.playerMap, map2 = player2.storage.oljuanxia_counter;
          if (!map2) {
            return false;
          }
          for (var i in map2) {
            if (map1[i] && map1[i].isIn() && player2.canUse("sha", map1[i], false)) {
              return true;
            }
          }
          return false;
        },
        logTarget(event2, player2) {
          var list = [];
          var map1 = _status.connectMode ? lib.playerOL : game.playerMap, map2 = player2.storage.oljuanxia_counter;
          if (!map2) {
            return false;
          }
          for (var i in map2) {
            if (map1[i] && map1[i].isIn()) {
              list.push(map1[i]);
            }
          }
          return list;
        },
        async content(event2, trigger2, player2) {
          const list = [];
          const map1 = _status.connectMode ? lib.playerOL : game.playerMap, map2 = player2.storage.oljuanxia_counter;
          if (!map2) {
            return false;
          }
          for (const i in map2) {
            if (map1[i] && map1[i].isIn()) {
              list.push(map1[i]);
            }
          }
          list.sortBySeat();
          event2.num = 0;
          event2.targets = list;
          let result = event2._result;
          while (true) {
            const target2 = event2.targets[event2.num];
            event2.target = target2;
            if (target2.isIn() && player2.canUse("sha", target2, false)) {
              const boolResult = await player2.chooseBool("狷狭：是否视为对" + get.translation(target2) + "依次使用" + get.cnNumber(player2.storage.oljuanxia_counter[target2.playerid]) + "张【杀】？").set("goon", get.effect(target2, { name: "sha" }, player2, player2) > 0).set("ai", () => _status.event.goon).forResult();
              if (boolResult) {
                result = boolResult;
              }
            }
            event2.num++;
            if (result.bool) {
              event2.count = player2.storage.oljuanxia_counter[target2.playerid];
              while (true) {
                event2.count--;
                if (target2.isIn() && player2.canUse("sha", target2, false)) {
                  const useCardResult = await player2.useCard({ name: "sha", isCard: true }, target2, false).forResult();
                  if (useCardResult) {
                    result = useCardResult;
                  }
                }
                if (event2.count > 0) {
                  continue;
                }
                break;
              }
              if (event2.num < event2.targets.length) {
                continue;
              }
              return;
            } else if (event2.num < event2.targets.length) {
              continue;
            } else {
              event2.finish();
              return;
            }
          }
        }
      }
    }
  }

