      dialog(event2, player2) {
        var list = [];
        for (var i of lib.inpile) {
          if (get.type(i) == "basic" && event2.filterCard({ name: i, isCard: true }, player2, event2)) {
            list.push(["基本", "", i]);
            if (i == "sha") {
              for (var j of lib.inpile_nature) {
                list.push(["基本", "", "sha", j]);
              }
            }
          }
        }
        return ui.create.dialog("锦织", [list, "vcard"], "hidden");
      },
      check(button) {
        if (_status.event.getParent().type != "phase") {
          return 1;
        }
        if (button.link[2] == "shan") {
          return 3;
        }
        var player2 = _status.event.player;
        if (button.link[2] == "jiu") {
          if (player2.getUseValue({ name: "jiu" }) <= 0) {
            return 0;
          }
          if (player2.countCards("h", "sha")) {
            return player2.getUseValue({ name: "jiu" });
          }
        }
        return player2.getUseValue({ name: button.link[2], nature: button.link[3] }) / 4;
      },
      backup(links, player2) {
        return {
          selectCard: player2.countMark("jinzhi_used") + 1,
          filterCard(card2, player3) {
            if (ui.selected.cards.length) {
              if (get.color(card2) != get.color(ui.selected.cards[0])) {
                return false;
              }
            }
            return lib.filter.cardDiscardable.apply(this, arguments);
          },
          complexCard: true,
          viewAs: {
            name: links[0][2],
            nature: links[0][3],
            suit: "none",
            number: null,
            isCard: true
          },
          position: "he",
          ignoreMod: true,
          check(card2) {
            var player3 = _status.event.player, color = get.color(card2, player3);
            if (player3.countCards("he", { color }) <= player3.countMark("jinzhi_used") || ui.selected.cards.length && get.color(ui.selected.cards[0], player3) != color) {
              return -1;
            }
            if (lib.skill.jinzhi_backup.viewAs.name == "jiu" && !player3.countCards("h", function(cardx) {
              return card2 != cardx && !ui.selected.cards.includes(cardx) && get.name(cardx, player3) == "sha";
            })) {
              return 0;
            }
            return Math.min(0.01, 6 - get.value(card2));
          },
          log: false,
          async precontent(event2, trigger2, player3) {
            player3.logSkill("jinzhi");
            player3.addTempSkill("jinzhi_used", "roundStart");
            player3.addMark("jinzhi_used", 1, false);
            var cards2 = event2.result.cards;
            await player3.discard(cards2);
            await player3.draw();
            event2.result.card = {
              name: event2.result.card.name,
              nature: event2.result.card.nature,
              isCard: true
            };
            event2.result.cards = [];
            if (cards2.length > 1) {
              var color = get.color(cards2[0], player3);
              for (var i = 1; i < cards2.length; i++) {
                if (get.color(cards2[i], player3) != color) {
                  var evt = event2.getParent();
                  evt.set("jinzhi", true);
                  evt.goto(0);
                  return;
                }
              }
            }
          }
        };
      },
      prompt(links, player2) {
        var name = links[0][2];
        var nature = links[0][3];
        return "弃置" + get.cnNumber(player2.countMark("jinzhi_used") + 1) + "张颜色相同的牌并摸一张牌，然后视为使用" + (get.translation(nature) || "") + get.translation(name);
      }
    },
    ai: {
      order(item, player2) {
        if (_status.event.type == "phase" && !player2.countMark("jinzhi_used") && player2.getUseValue({ name: "jiu" }, null, true) > 0 && player2.countCards("h", "sha")) {
          return get.order({ name: "jiu" }) + 1;
        }
        return 1;
      },
      respondShan: true,
      respondSha: true,
      skillTagFilter(player2) {
        if (player2.countMark("jinzhi_used") >= player2.countCards("he")) {
          return false;
        }
      },
      result: {
        player(player2) {
          if (_status.event.dying) {
            return get.attitude(player2, _status.event.dying);
          }
          return 1;
        }
      }
    },
    subSkill: {
      used: {
        charlotte: true,
        onremove: true,
        intro: { content: "本轮已发动过#次" }
      }
    }
  }

sp:youlong.code:
{
    enable: "chooseToUse",
    audio: 2,
    audioname: ["key_sakuya"],
    zhuanhuanji: true,
    marktext: "☯",
    mark: true,
    intro: {
      content(storage, player2) {
        return `每轮限一次，你可以废除你的一个装备栏，视为使用一张未以此法使用过的${storage ? "基本" : "普通锦囊"}牌。`;
      }
    },
    init(player2) {
      player2.storage.youlong = false;
      if (!player2.storage.youlong2) {
        player2.storage.youlong2 = [];
      }
    },
    hiddenCard(player2, name) {
      if (!player2.hasEnabledSlot()) {
        return false;
      }
      if (get.inpileVCardList().some((info) => info[2] === name && player2.getStorage("youlong2").some((item) => item.name === info[2] && item.nature === info[3]))) {
        return false;
      }
      if (player2.getStorage("youlong_used").includes(player2.storage.youlong || false)) {
        return false;
      }
      const type = get.type(name);
      if (player2.storage.youlong) {
        return type == "basic";
      }
      return type == "trick";
    },
    filter(event2, player2) {
      if (!player2.hasEnabledSlot()) {
        return false;
      }
      if (player2.getStorage("youlong_used").includes(player2.storage.youlong || false)) {
        return false;
      }
      const type = player2.storage.youlong ? "basic" : "trick";
      return get.inpileVCardList((info) => {
        if (info[0] != type) {
          return false;
        }
        if (player2.getStorage("youlong2").some((item) => item.name === info[2] && item.nature === info[3])) {
          return false;
        }
        return event2.filterCard({ name: info[2], nature: info[3], isCard: true }, player2, event2);
      }).length;
    },
    chooseButton: {
      dialog(event2, player2) {
        const dialog = ui.create.dialog("游龙", "hidden");
        const equips = [];
        for (let i = 1; i < 6; i++) {
          if (!player2.hasEnabledSlot(i)) {
            continue;
          }
          equips.push([i, get.translation("equip" + i)]);
        }
        if (equips.length > 0) {
          dialog.add([equips, "tdnodes"]);
        }
        const type = player2.storage.youlong ? "basic" : "trick";
        const list = get.inpileVCardList((info) => {
          if (info[0] != type) {
            return false;
          }
          if (player2.getStorage("youlong2").some((item) => item.name === info[2] && item.nature === info[3])) {
            return false;
          }
          return event2.filterCard({ name: info[2], nature: info[3], isCard: true }, player2, event2);
        });
        dialog.add([list, "vcard"]);
        return dialog;
      },
      filter(button) {
        if (ui.selected.buttons.length && typeof button.link == typeof ui.selected.buttons[0].link) {
          return false;
        }
        return true;
      },
      select: 2,
      check(button) {
        const player2 = get.player();
        if (typeof button.link == "number") {
          const card2 = player2.getEquip(button.link);
          if (card2) {
            const val = get.value(card2);
            if (val > 0) {
              return 0;
            }
            return 5 - val;
          }
          switch (button.link) {
            case 3:
              return 4.5;
            case 4:
              return 4.4;
            case 5:
              return 4.3;
            case 2:
              return (3 - player2.hp) * 1.5;
            case 1: {
              if (game.hasPlayer((current) => {
                return (get.realAttitude || get.attitude)(player2, current) < 0 && get.distance(player2, current) > 1;
              })) {
                return 0;
              }
              return 3.2;
            }
          }
        }
        const name = button.link[2];
        const evt = get.event().getParent();
        if (evt.type == "phase") {
          const card2 = { name, nature: button.link[3], isCard: true };
          if (name == "shan") {
            return 2;
          }
          if (evt.type == "dying") {
            if (get.attitude(player2, evt.dying) < 2) {
              return false;
            }
            if (name == "jiu") {
              return 2.1;
            }
            return 1.9;
          }
          return player2.getUseValue(card2);
        }
        return 1;
      },
      backup(links, player2) {
        if (typeof links[1] == "number") {
          links.reverse();
        }
        const equip = links[0];
        const name = links[1][2];
        const nature = links[1][3];
        return {
          filterCard: () => false,
          selectCard: -1,
          equip,
          viewAs: {
            name,
            nature,
            isCard: true
          },
          popname: true,
          log: false,
          async precontent(event2, trigger2, player3) {
            player3.logSkill("youlong");
            await player3.disableEquip(lib.skill.youlong_backup.equip);
            player3.addTempSkill("youlong_used", "roundStart");
            player3.markAuto("youlong_used", [player3.storage.youlong || false]);
            player3.changeZhuanhuanji("youlong");
            player3.storage.youlong2.add(event2.result.card);
          }
        };
      },
      prompt(links, player2) {
        if (typeof links[1] == "number") {
          links.reverse();
        }
        const equip = "equip" + links[0];
        const name = links[1][2];
        const nature = links[1][3];
        return "废除自己的" + get.translation(equip) + "栏，视为使用" + (get.translation(nature) || "") + get.translation(name);
      }
    },
    ai: {
      respondSha: true,
      respondShan: true,
      fireAttack: true,
      skillTagFilter(player2, tag, arg) {
        if (arg == "respond") {
          return false;
        }
        if (!player2.storage.youlong || player2.getStorage("youlong_used").includes(true)) {
          return false;
        }
        const name = tag == "respondSha" ? "sha" : "shan";
        if (name == "shan") {
          if (player2.getStorage("youlong2").some((item) => item.name === "shan")) {
            return false;
          }
        } else if (name == "sha") {
          if ([void 0].concat(lib.inpile_nature.slice(0)).every((nature) => player2.getStorage("youlong2").some((item) => item.name === "sha" && item.nature === nature))) {
            return false;
          }
        } else if (tag == "fireAttack") {
          const type = player2.storage.youlong ? "basic" : "trick";
          return get.inpileVCardList((info) => {
            if (info[0] != type) {
              return false;
            }
            return !player2.getStorage("youlong2").some((item) => item.name === info[2] && item.nature === info[3]);
          }).some((info) => {
            return get.tag({ name: info[2], nature: info[3], isCard: true }, "fireDamage");
          });
        }
      },
      order(item, player2) {
        if (player2 && _status.event.type == "phase") {
          let max = 0;
          const type = player2.storage.youlong ? "basic" : "trick";
          let list = get.inpileVCardList((info) => {
            if (info[0] != type) {
              return false;
            }
            return !player2.getStorage("youlong2").some((item2) => item2.name === info[2] && item2.nature === info[3]);
          }).map((info) => {
            return { name: info[2], nature: info[3], isCard: true };
          });
          for (const card2 of list) {
            if (player2.getUseValue(card2) > 0) {
              const temp = get.order(card2);
              if (temp > max) {
                max = temp;
              }
            }
          }
          if (max > 0) {
            max += 0.3;
          }
          return max;
        }
        return 1;
      },
      result: {
        player(player2) {
          if (_status.event.dying) {
            return get.attitude(player2, _status.event.dying);
          }
          return 1;
        }
      }
    },
    subSkill: { used: { charlotte: true, onremove: true } }
  }

sp:luanfeng.code:
{
    audio: 2,
    audioname: ["key_sakuya"],
    trigger: { global: "dying" },
    filter(event2, player2) {
      return event2.player.maxHp >= player2.maxHp && event2.player.hp < 1;
    },
    limited: true,
    skillAnimation: true,
    animationColor: "soil",
    logTarget: "player",
    check(event2, player2) {
      if (get.attitude(player2, event2.player) < 4) {
        return false;
      }
      if (player2.countCards("h", function(card2) {
        var mod2 = game.checkMod(card2, player2, "unchanged", "cardEnabled2", player2);
        if (mod2 != "unchanged") {
          return mod2;
        }
        var mod = game.checkMod(card2, player2, event2.player, "unchanged", "cardSavable", player2);
        if (mod != "unchanged") {
          return mod;
        }
        var savable = get.info(card2).savable;
        if (typeof savable == "function") {
          savable = savable(card2, player2, event2.player);
        }
        return savable;
      }) >= 1 - event2.player.hp) {
        return false;
      }
      if (event2.player == player2 || event2.player == get.zhu(player2)) {
        return true;
      }
      return !player2.hasUnknown();
    },
    async content(event2, trigger2, player2) {
      player2.awakenSkill(event2.name);
      await trigger2.player.recover(3 - trigger2.player.hp);
      const list = [], target2 = trigger2.player;
      for (let i = 1; i < 6; i++) {
        for (let j = 0; j < target2.countDisabledSlot(i); j++) {
          list.push(i);
        }
      }
      if (list.length > 0) {
        await target2.enableEquip(list);
      }
      if (list.length < 6) {
        const next = target2.drawTo(6 - list.length);
        if (target2.storage.kotarou_rewrite) {
          target2.storage.kotarou_rewrite = [];
        }
        if (player2 == target2) {
          player2.storage.youlong2 = [];
        }
        await next;
      }
    }
  }

sp2:mubing.code:
{
    audio: 2,
    audioname: ["sp_key_yuri"],
    trigger: { player: "phaseUseBegin" },
    //direct:true,
    frequent: true,
    filter(event, player) {
      return player.hasCards("he");
    },
    async content(event, trigger, player) {
      const num = player.storage.mubing2 ? 4 : 3;
      const cards2 = get.cards(num);
      const orderingEvent = game.cardsGotoOrdering(cards2);
      game.log(player, "展示了", cards2);
      const videoId = lib.status.videoId++;
      game.broadcastAll(
        (player2, id, cards3) => {
          const prompt = `${get.translation(player2)}发动了【募兵】`;
          const dialog = ui.create.dialog(prompt, cards3);
          dialog.videoId = id;
        },
        player,
        videoId,
        cards2
      );
      game.addVideo("showCards", player, [`${get.translation(player)}发动了【募兵】`, get.cardsInfo(cards2)]);
      await orderingEvent;
      await game.delay(2);
      cards2.sort((a, b) => a.number - b.number);
      const numa = cards2.reduce((sum, card) => get.value(card, player) > 0 ? sum + get.number(card) : sum, 0);
      const updateDialogPrompt = (id, prompt) => {
        const dialog = get.idDialog(id);
        if (dialog) {
          dialog.content.firstChild.innerHTML = prompt;
        }
      };
      const discardEvent = player.chooseToDiscard({
        selectCard: [1, Infinity],
        position: "h",
        ai: (card) => {
          const player2 = _status.event.player;
          const numa2 = _status.event.numa;
          const selectedNumber = ui.selected.cards.reduce((sum, selectedCard) => sum + selectedCard.number, 0);
          if (selectedNumber >= numa2) {
            return 0;
          }
          if (card.number + selectedNumber >= numa2) {
            return 15 - get.value(card);
          }
          if (!ui.selected.cards.length) {
            const min = _status.event.min;
            if (card.number < min && !player2.countCards("h", (xcard) => xcard !== card && card.number + xcard.number > min)) {
              return 0;
            }
            return card.number;
          }
          return Math.max(5 - get.value(card), card.number);
        }
      }).set("prompt", false).set("numa", numa).set("min", cards2[0].number);
      if (player === game.me) {
        updateDialogPrompt(videoId, "请选择要弃置的牌");
      } else if (player.isOnline()) {
        player.send(updateDialogPrompt, videoId, "请选择要弃置的牌");
      }
      const discardResult = await discardEvent.forResult();
      let selectedCards = [];
      if (discardResult.bool) {
        const maxNum = discardResult.cards.reduce((sum, card) => sum + get.number(card), 0);
        const buttonEvent = player.chooseButton({
          selectButton: [0, num],
          filterButton: (button) => {
            const selectedNumber = ui.selected.buttons.reduce((sum, selectedButton) => sum + get.number(selectedButton.link), 0);
            return selectedNumber + get.number(button.link) <= _status.event.maxNum;
          },
          ai: (button) => get.value(button.link, _status.event.player)
        }).set("dialog", videoId).set("maxNum", maxNum);
        if (player === game.me) {
          updateDialogPrompt(videoId, "请选择要获得的牌");
        } else if (player.isOnline()) {
          player.send(updateDialogPrompt, videoId, "请选择要获得的牌");
        }
        const buttonResult = await buttonEvent.forResult();
        if (buttonResult.bool) {
          selectedCards = buttonResult.links;
        }
      }
      game.broadcastAll("closeDialog", videoId);
      game.addVideo("cardDialog", null, videoId);
      if (!selectedCards.length) {
        return;
      }
      await player.gain({ cards: selectedCards, log: true, animate: "gain2" });
      if (!player.storage.mubing2) {
        return;
      }
      const given = [];
      let remainingCards = [...selectedCards];
      for (let i = 1; i < game.countPlayer(); i++) {
        const handCards = player.getCards("h");
        remainingCards = remainingCards.filter((card) => handCards.includes(card));
        if (!remainingCards.length || !game.hasPlayer((current) => current !== player && !given.includes(current))) {
          break;
        }
        const giveResult = await player.chooseCardTarget({
          prompt: "是否将得到的牌中的任意张交给其他角色？",
          selectCard: [1, remainingCards.length],
          filterCard: (card) => _status.event.cards.includes(card),
          filterTarget: (_card, player2, target2) => target2 !== player2 && !_status.event.given.includes(target2),
          cards: remainingCards,
          given,
          ai1: () => -1
        }).forResult();
        if (!giveResult.bool) {
          break;
        }
        const target = giveResult.targets[0];
        const cardsToGive = giveResult.cards;
        given.push(target);
        remainingCards.removeArray(cardsToGive);
        player.line(target, "green");
        await player.give(cardsToGive, target);
      }
    }
  }

sp2:ziqu.code:
{
    audio: 2,
    audioname: ["sp_key_yuri"],
    trigger: { source: "damageBegin2" },
    filter(event, player) {
      return event.player !== player && !player.getStorage("ziqu").includes(event.player);
    },
    check(event, player) {
      const target = event.player;
      const eff = get.damageEffect(target, player, player);
      if (get.attitude(player, target) > 0) {
        if (eff >= 0) {
          return false;
        }
        return true;
      }
      if (eff <= 0) {
        return true;
      }
      if (target.hp === 1) {
        return false;
      }
      if (event.num > 1) {
        return false;
      }
      const cards2 = target.getCards("he");
      for (const card of cards2) {
        if (get.number(card) > 10) {
          return true;
        }
      }
      return false;
    },
    logTarget: "player",
    async content(event, trigger, player) {
      trigger.cancel();
      if (!player.storage.ziqu) {
        player.storage.ziqu = [];
      }
      player.storage.ziqu.push(trigger.player);
      player.markSkill("ziqu");
      const result = await trigger.player.chooseCard({
        forced: true,
        position: "he",
        filterCard: (card, player2) => !player2.hasCards("he", (cardx) => cardx.number > card.number)
      }).forResult();
      if (!result.bool || !result.cards?.length) {
        return;
      }
      await trigger.player.give(result.cards, player);
    },
    intro: { content: "已对$发动过" }
  }

sp2:diaoling.code:
{
    audio: 2,
    audioname: ["sp_key_yuri"],
    trigger: { player: "phaseZhunbeiBegin" },
    forced: true,
    juexingji: true,
    skillAnimation: true,
    animationColor: "metal",
    filter(event, player) {
      let num = 0;
      player.getAllHistory("gain", (evt) => {
        const evt2 = evt.getParent();
        if (evt2.name === "mubing" && evt2.player === player) {
          num += evt.cards.filter((card) => card.name === "sha" || get.subtype(card, false) === "equip1" || get.type2(card, false) === "trick" && get.tag({ name: card.name }, "damage")).length;
        }
      });
      return num >= 6;
    },
    async content(event, trigger, player) {
      player.awakenSkill(event.name);
      player.storage.mubing2 = true;
      player.markSkill("mubing_rewrite");
      await player.chooseDrawRecover(2, true);
    },
    ai: {
      combo: "mubing"
    },
    derivation: "mubing_rewrite"
  }

sp2:mubing_rewrite.code:
