sp:retuogu.code:
{
    audio: "tuogu",
    trigger: { global: "die" },
    filter(event2, player2) {
      return event2.player.getStockSkills("仲村由理", "天下第一").filter(function(skill) {
        var info = get.info(skill);
        return info && !info.juexingji && !info.hiddenSkill && !info.zhuSkill && !info.charlotte && !info.limited && !info.dutySkill;
      }).length > 0;
    },
    logTarget: "player",
    check(event2, player2) {
      var list = event2.player.getStockSkills("仲村由理", "天下第一").filter(function(skill) {
        var info = get.info(skill);
        return info && !info.juexingji && !info.hiddenSkill && !info.zhuSkill && !info.charlotte && !info.limited && !info.dutySkill;
      });
      var negSkill = list.some(function(skill) {
        return get.skillRank(skill, "inout") <= 0;
      });
      var att = get.sgnAttitude(event2.player, player2);
      if (!player2.storage.retuogu) {
        if (negSkill && att < 0) {
          return false;
        }
