              }) > 0;
            }
            return current.countCards("ej", function(card2) {
              return get.position(card2) == "j" || get.value(card2, current) <= 0;
            }) > 0;
          })) {
            return 1;
          }
          return 0;
        }).forResult();
      } else {
        result = await player2.chooseControl("ok", "cancel2").set("prompt", get.prompt2("neifa")).forResult();
      }
      if (result.control == "cancel2") {
        delete _status.noclearcountdown;
        if (!_status.noclearcountdown) {
          game.stopCountChoose();
        }
        event2.finish();
        return;
      } else if (result.index == 1) {
        const result2 = await player2.chooseTarget("请选择一名角色，获得其装备区或判定区内的一张牌", true, function(card2, player3, target2) {
          return target2.countGainableCards(player3, "ej") > 0;
        }).set("ai", function(target2) {
          var player3 = _status.event.player;
          var att = get.attitude(player3, target2);
          if (att > 0 && target2.countCards("ej", function(card2) {
            return get.position(card2) == "j" || get.value(card2, target2) <= 0;
          })) {
            return 2 * att;
          } else if (att < 0 && target2.countCards("e", function(card2) {
            return get.value(card2, target2) > 5;
          })) {
            return -att;
          }
          return -1;
        }).forResult();
        delete _status.noclearcountdown;
        if (!_status.noclearcountdown) {
          game.stopCountChoose();
        }
        if (result2.bool) {
          const target2 = result2.targets[0];
          player2.logSkill("neifa", target2);
          await player2.gainPlayerCard(target2, "ej", true);
        }
      } else {
        delete _status.noclearcountdown;
        if (!_status.noclearcountdown) {
          game.stopCountChoose();
        }
        player2.logSkill("neifa");
        await player2.draw(2);
      }
      const result3 = await player2.chooseToDiscard(true, "he").set("ai", function(cardx) {
        var card2 = event2.card;
        var player3 = _status.event.player;
        var num = 0;
        var hs = player3.getCards("h");
        var muniu = player3.getEquip("muniu");
        var subs = [];
        if (muniu && muniu.cards) {
          hs = hs.concat(muniu.cards);
        }
        if (get.type(cardx) == "basic") {
          var shas = hs.filter(function(card3) {
            return card3 != cardx && get.name(card3, player3) == "sha" && player3.hasValueTarget(card3);
          });
          var numx = player3.countCards("h", function(card3) {
            return get.type2(card3, player3) != "basic";
          });
          num += Math.min(numx, Math.max(0, shas.length - player3.getCardUsable("sha"))) * 0.7;
          num += Math.min(
            player3.getCardUsable("sha") + numx,
            shas.filter(function(card3) {
              return game.countPlayer(function(current) {
                return player3.canUse(card3, current) && get.effect(current, card3, player3, player3) > 0;
              }) > 1;
            }).length
          ) * 1.1;
          var taos = Math.min(
            player3.maxHp - player3.hp,
            hs.filter(function(card3) {
              return cardx != card3 && get.name(card3, player3) == "tao";
            }).length
          );
          num += taos * player3.getDamagedHp() * 1.2;
        } else {
          var numx = Math.sqrt(
            Math.min(
              5,
              player3.countCards("h", function(card3) {
                return get.type2(card3, player3) == "basic";
              })
            )
          );
          if (numx) {
            num += numx * Math.min(
              2,
              hs.filter(function(card3) {
                if (card3 == cardx || get.type(card3) != "equip" || !player3.hasUseTarget(card3)) {
                  return false;
                }
                subs.add(get.subtype(card3));
                return true;
              }).length
            ) * (2.5 + player3.countCards("e")) / 2.5;
          }
          num += hs.filter(function(card3) {
            return card3 != cardx && get.type2(card3) == "trick" && player3.hasValueTarget(card3);
          }).length * 0.65;
        }
        if (get.position(cardx) == "e" && cardx.name != "muniu" && subs.includes(get.subtype(card2))) {
          num += 3;
        }
        return num * 1.5 - get.value(cardx);
      }).forResult();
      if (result3.bool && result3.cards && result3.cards.length) {
        const name = get.type(result3.cards[0]) == "basic" ? "neifa_basic" : "neifa_nobasic";
        player2.addTempSkill(name);
        const num = Math.min(
          5,
          player2.countCards("h", function(cardx) {
            return name == "neifa_basic" != (get.type2(cardx, player2) == "basic");
          })
        );
        if (num > 0) {
          player2.addMark(name, num, false);
        } else {
          player2.storage[name] = 0;
        }
      }
    },
    ai: {
      threaten: 3
    }
  }

