sp:ollingren.code:
{
    audio: "xinfu_lingren",
    //trigger: { player: "useCardToPlayered" },
    trigger: { player: "useCard" },
    filter(event2, player2) {
      if (!["basic", "trick"].includes(get.type(event2.card))) {
        return false;
      }
      return get.is.damageCard(event2.card) && event2.targets?.length > 0;
    },
    usable: 1,
    derivation: ["new_rejianxiong", "rexingshang"],
    async cost(event2, trigger2, player2) {
      event2.result = await player2.chooseTarget(get.prompt(event2.skill), "选择一名目标角色并猜测其手牌构成", (card2, player3, target2) => {
        return _status.event.targets.includes(target2);
      }).set("ai", (target2) => {
        return 2 - get.attitude(get.player(), target2);
      }).set("targets", trigger2.targets).forResult();
    },
    async content(event2, trigger2, player2) {
      const {
        targets: [target2]
      } = event2;
      const list = ["basic", "trick", "equip"].map((type) => ["", "", "caoying_" + type]);
      const result = await player2.chooseButton(["凌人：猜测其有哪些类别的手牌", [list, "vcard"]], [0, 3], true).set("ai", (button) => {
        return get.event().choice.includes(button.link[2].slice(8));
      }).set(
        "choice",
        (() => {
          if (!target2.countCards("h")) {
            return [];
          }
          let choice = [], known = target2.getKnownCards(player2), unknown = target2.getCards("h", (i) => !known.includes(i));
          for (let i of known) {
            choice.add(get.type2(i, target2));
          }
          if (!unknown.length || choice.length > 2) {
            return choice;
          }
          let rand = 0.05;
          if (!choice.includes("basic")) {
            if (unknown.some((i) => get.type(i, null, target2) === "basic")) {
              rand = 0.95;
            }
            if (Math.random() < rand) {
              choice.push("basic");
            }
          }
          if (!choice.includes("trick")) {
            if (unknown.some((i) => get.type(i, "trick", target2) === "trick")) {
              rand = 0.9;
            } else {
              rand = 0.1;
            }
            if (Math.random() < rand) {
              choice.push("trick");
            }
          }
          if (!choice.includes("equip")) {
            if (unknown.some((i) => get.type(i, null, target2) === "equip")) {
              rand = 0.75;
            } else {
              rand = 0.25;
            }
            if (Math.random() < rand) {
              choice.push("equip");
            }
          }
          return choice;
        })()
      ).forResult();
      if (!result?.bool) {
        return;
      }
      const choices = result.links.map((i) => i[2].slice(8));
      if (!event2.isMine() && !event2.isOnline()) {
        await game.delayx();
      }
      let num = 0;
      ["basic", "trick", "equip"].forEach((type) => {
        if (choices.includes(type) == target2.hasCard((card2) => get.type2(card2, target2) === type, "h")) {
          num++;
        }
      });
      player2.popup("猜对" + get.cnNumber(num) + "项");
      game.log(player2, "猜对了" + get.cnNumber(num) + "项");
      if (num > 0) {
        player2.addTempSkill(`${event2.name}_damage`);
        const map = player2.getStorage(`${event2.name}_damage`, {});
        map[target2.playerid] ??= 0;
        map[target2.playerid]++;
        player2.setStorage(`${event2.name}_damage`, map, true);
      }
      if (num > 1) {
        if (trigger2.addCount != false) {
          trigger2.addCount = false;
          const stat = player2.getStat().card, name = trigger2.card.name;
          if (typeof stat[name] == "number") {
            stat[name]--;
          }
          game.log(trigger2.card, "不计入次数");
        }
        await player2.draw(2);
      }
      if (num > 2) {
        await player2.addTempSkills(get.info(event2.name).derivation, { player: "phaseBegin" });
      }
    },
    ai: { threaten: 2.4 },
    subSkill: {
      damage: {
        audio: "ollingren",
        charlotte: true,
        onremove: true,
        init(player2, skill) {
          player2.storage[skill] = {};
        },
        intro: {
          name: "凌人（加伤）",
          markcount: () => 0,
          content(storage, player2) {
            if (!storage) {
              return "无效果";
            }
            let str = "";
            for (const id in storage) {
              const target2 = _status.connectMode ? lib.playerOL[id] : game.playerMap[id];
              const num = storage[id];
              str += `<li>${get.translation(target2)}：+${num}<br>`;
            }
            return str;
          }
        },
        trigger: {
          source: "damageBegin1"
        },
        filter(event2, player2) {
          return player2.getStorage("ollingren_damage", {})[event2.player.playerid] > 0;
        },
        forced: true,
        logTarget: "player",
        async content(event2, trigger2, player2) {
          const {
            targets: [target2]
          } = event2;
          const storage = player2.getStorage(event2.name, {});
          const num = storage[target2.playerid];
          delete storage[target2.playerid];
          if (!Object.keys(storage).length) {
            player2.removeSkill(event2.name);
          } else {
            player2.setStorage(event2.name, storage, true);
          }
          trigger2.num += num;
        }
      }
    }
  }

