      return event2.lianhuanable == true && event2.player.isIn();
    },
    frequent: true,
    async content(event2, trigger2, player2) {
      event2.cards = game.cardsGotoOrdering(
        get.cards(
          game.countPlayer(function(current) {
            return current.isLinked();
          }) + 1
        )
      ).cards;
      if (_status.connectMode) {
        game.broadcastAll(function() {
          _status.noclearcountdown = true;
        });
      }
      event2.given_map = {};
      while (true) {
        let result;
        if (event2.cards.length > 1) {
          result = await player2.chooseCardButton("称好：请选择要分配的牌", true, event2.cards, [1, event2.cards.length]).set("ai", function(button) {
            if (ui.selected.buttons.length == 0) {
              return 1;
            }
            return 0;
          }).forResult();
        } else if (event2.cards.length == 1) {
          event2._result = { links: event2.cards.slice(0), bool: true };
          result = event2._result;
        } else {
          event2.finish();
          return;
        }
        if (result.bool) {
          event2.cards.removeArray(result.links);
          event2.togive = result.links.slice(0);
          result = await player2.chooseTarget("选择一名角色获得" + get.translation(result.links), true).set("ai", function(target2) {
            var att = get.attitude(_status.event.player, target2);
            if (_status.event.enemy) {
              return -att;
            } else if (att > 0) {
              return att / (1 + target2.countCards("h"));
            } else {
              return att / 100;
            }
          }).set("enemy", get.value(event2.togive[0], player2, "raw") < 0).forResult();
        }
        if (result.targets.length) {
          const id = result.targets[0].playerid, map = event2.given_map;
          if (!map[id]) {
            map[id] = [];
          }
          map[id].addArray(event2.togive);
        }
        if (event2.cards.length <= 0) {
          break;
        }
      }
      if (_status.connectMode) {
        game.broadcastAll(function() {
          delete _status.noclearcountdown;
          game.stopCountChoose();
        });
      }
      const list = [];
      for (const i in event2.given_map) {
        const source = (_status.connectMode ? lib.playerOL : game.playerMap)[i];
        player2.line(source, "green");
        list.push([source, event2.given_map[i]]);
      }
