      } else {
        const list = ["令自己摸一张牌", "令XXX摸两张牌", "令XXX回复1点体力"];
        const card2 = get.translation(trigger2.player);
        result = await player2.chooseButton(
          [
            "【礼下】：请选择一至两项",
            [
              list.map((item, index) => {
                return [index, item.replace(/XXX/g, card2)];
              }),
              "textbutton"
            ]
          ],
          true,
          [1, 2]
        ).set("dialog", event2.videoId).set("filterButton", function(button) {
          if (button.link == 2) {
            return _status.event.bool1;
          }
          return true;
        }).set("bool1", trigger2.player.isDamaged()).set("ai", function(button) {
          var player3 = _status.event.player;
          var event3 = _status.event.getTrigger();
