    },
    round: 1,
    async cost(event2, trigger2, player2) {
      const { player: target2 } = trigger2;
      event2.result = await player2.chooseTarget(get.prompt2(event2.skill), (card2, player3, target3) => {
        return target3 != player3 && target3 != get.event().targetx;
      }).set("ai", (target3) => {
        const { player: player3, targetx } = get.event();
        if (get.attitude(player3, targetx) > 0) {
          const att1 = get.attitude(target3, player3);
          const att2 = get.attitude(target3, targetx);
          const att3 = get.attitude(player3, target3);
          if (att3 < 0) {
            return 0;
          }
          return att1 / 2 + att2 + att3;
        }
        return 0;
      }).set("targetx", target2).forResult();
    },
    async content(event2, trigger2, player2) {
      const {
        targets: [target2]
      } = event2;
      await target2.draw(4);
