        return;
      }
      const { player: tosave } = trigger2;
      const att = get.attitude(target2, tosave);
      const hastao = target2.countCards("hs", (card2) => target2.canSaveCard(card2, tosave)) >= 1 - tosave.hp;
      const result = await target2.chooseToDiscard(4, true, "he").set("ai", (card2) => {
        const { hastao: hastao2, att: att2 } = get.event();
        if (!hastao2 && att2 > 0) {
          const suit = get.suit(card2);
