sp:danji.code:
{
    audio: 2,
    skillAnimation: true,
    animationColor: "water",
    trigger: { player: "phaseZhunbeiBegin" },
    forced: true,
    juexingji: true,
    derivation: ["mashu", "nuzhan"],
    filter(event2, player2) {
      var zhu = get.zhu(player2);
      if (zhu && zhu.isZhu) {
        var name = zhu.name;
        while (name.indexOf("_") != -1) {
          name = name.slice(name.indexOf("_") + 1);
        }
        if (name.indexOf("liubei") == 0) {
          return false;
        }
      }
      return !player2.storage.danji && player2.countCards("h") > player2.hp;
    },
    content() {
      player.awakenSkill(event.name);
      player.loseMaxHp();
      player.addSkills(["mashu", "nuzhan"]);
    },
    ai: {
      maixie: true,
      skillTagFilter: (player2, tag, arg) => {
        if (tag === "maixie") {
          if (player2.hp < 2 || player2.storage.danji || player2.hasSkill("nuzhan") || player2.countCards("h") !== player2.hp) {
            return false;
          }
          let zhu = get.zhu(player2);
          if (zhu && zhu.isZhu) {
            let name = zhu.name;
            while (name.indexOf("_") !== -1) {
              name = name.slice(name.indexOf("_") + 1);
            }
            if (name.indexOf("liubei") == 0) {
              return false;
            }
          }
          return true;
        }
      },
      effect: {
        target: (card2, player2, target2) => {
          let hs = target2.countCards("h");
          if (target2.hp < 3 || target2.storage.danji || target2.hasSkill("nuzhan") || hs > target2.hp + 1) {
            return;
          }
          let zhu = get.zhu(target2);
          if (zhu && zhu.isZhu) {
            let name = zhu.name;
            while (name.indexOf("_") !== -1) {
              name = name.slice(name.indexOf("_") + 1);
            }
            if (name.indexOf("liubei") == 0) {
              return;
            }
          }
          if (get.tag(card2, "draw")) {
            return 1.6;
          }
          if (get.tag(card2, "lose") || get.tag(card2, "discard")) {
            return [1, -0.8];
          }
          if (hs === target2.hp && get.tag(card2, "damage")) {
            return [1, target2.hp / 3];
          }
          if (hs > target2.hp && target2.hp > 3 && (card2.name === "shan" || card2.name === "wuxie")) {
            return "zeroplayertarget";
          }
        }
      },
      combo: "new_rewusheng"
    }
  }

