{
    trigger: { player: "phaseZhunbeiBegin" },
    filter(event2, player2) {
      return player2.getExpansions("yinbing").length > 0;
    },
    forced: true,
    audio: 2,
    async content(event2, trigger2, player2) {
      const result = await player2.chooseTarget(get.prompt2("juedi"), true, function(card2, player3, target2) {
        return player3.hp >= target2.hp;
      }).set("ai", function(target2) {
        var player3 = _status.event.player;
        var att = get.attitude(player3, target2);
        if (att < 2) {
          return att - 10;
        }
        var num = att / 10;
        if (target2 == player3) {
          num += player3.maxHp - player3.countCards("h") + 0.5;
        } else {
          num += _status.event.n2 * 2;
          if (target2.isDamaged()) {
            if (target2.hp == 1) {
              num += 3;
            } else if (target2.hp == 2) {
              num += 2;
            } else {
              num += 0.5;
            }
          }
        }
        if (target2.hasJudge("lebu")) {
          num /= 2;
        }
        return num;
      }).set("n2", player2.getExpansions("yinbing").length).forResult();
      if (result.bool) {
        player2.line(result.targets[0], "green");
        const cards2 = player2.getExpansions("yinbing");
