          await target2.recover();
          await player2.give(cards2, target2, "give");
          await target2.draw(cards2.length);
        }
      }
    },
    ai: {
      combo: "yinbing"
    }
  }

sp:zhenwei.code:
{
    audio: 2,
    audioname: ["re_wenpin"],
    trigger: {
      global: "useCardToTarget"
    },
    direct: true,
    filter(event2, player2) {
      if (player2 == event2.target || player2 == event2.player) {
        return false;
      }
      if (!player2.countCards("he")) {
        return false;
      }
      if (event2.targets.length > 1) {
        return false;
      }
      if (!event2.target) {
        return false;
      }
      if (event2.target.hp >= player2.hp) {
        return false;
      }
      var card2 = event2.card;
      if (card2.name == "sha") {
        return true;
      }
      if (get.color(card2) == "black" && get.type(card2, "trick") == "trick") {
        return true;
      }
      return false;
    },
    async content(event2, trigger2, player2) {
      let save = false;
      if (get.attitude(player2, trigger2.target) > 2) {
        if (trigger2.card.name == "sha") {
          if (player2.countCards("h", "shan") || player2.getEquip(2) || trigger2.target.hp == 1 || player2.hp > trigger2.target.hp + 1) {
            if (!trigger2.target.countCards("h", "shan") || trigger2.target.countCards("h") < player2.countCards("h")) {
              save = true;
            }
          }
        } else if (trigger2.card.name == "juedou" && trigger2.target.hp == 1) {
          save = true;
        } else if (trigger2.card.name == "shunshou" && get.attitude(player2, trigger2.player) < 0 && get.attitude(trigger2.player, trigger2.target) < 0) {
          save = true;
        }
      }
      const next = player2.chooseToDiscard("he", get.prompt(event2.name, trigger2.target), "弃置一张牌，将" + get.translation(trigger2.card) + "转移给自己，或令此牌对其无效");
      next.logSkill = [event2.name, trigger2.target];
      next.set("ai", function(card2) {
        if (_status.event.aisave) {
          return 7 - get.value(card2);
        }
        return 0;
      });
      next.set("aisave", save);
      const result = await next.forResult();
      if (result.bool) {
        const result2 = await player2.chooseControl("转移", "失效", function() {
          var trigger3 = _status.event.getTrigger();
          var player3 = _status.event.player;
          if (trigger3.card.name == "sha") {
            if (player3.countCards("h", "shan")) {
              return "转移";
            }
          } else if (trigger3.card.name == "juedou") {
            if (player3.countCards("h", "sha")) {
              return "转移";
            }
          }
          return "失效";
        }).set("prompt", "将" + get.translation(trigger2.card) + "转移给你，或令其失效").forResult();
        if (result2.control == "转移") {
          const drawNext = player2.draw();
          trigger2.getParent().targets.remove(trigger2.target);
          trigger2.getParent().triggeredTargets2.remove(trigger2.target);
          trigger2.getParent().targets.push(player2);
          trigger2.untrigger();
          trigger2.player.line(player2);
          await drawNext;
          await game.delayx();
        } else {
          const cards2 = trigger2.cards.filterInD();
          if (cards2.length > 0) {
            trigger2.player.addSkill("zhenwei2");
            const addNext = trigger2.player.addToExpansion(cards2, "gain2");
            addNext.gaintag.add("zhenwei2");
            await addNext;
          }
          trigger2.targets.length = 0;
          trigger2.getParent().triggeredTargets2.length = 0;
        }
      } else {
        event2.finish();
        return;
      }
    },
    ai: {
      threaten: 1.1
    }
  }

