refresh:oltianxiang.code:
{
    audio: "tianxiang",
    audioname: ["daxiaoqiao", "re_xiaoqiao", "ol_xiaoqiao"],
    trigger: { player: "damageBegin4" },
    direct: true,
    filter(event, player) {
      return player.countCards("he", function(card) {
        if (_status.connectMode && get.position(card) == "h") {
          return true;
        }
        return get.suit(card, player) == "heart";
      }) > 0 && event.num > 0;
    },
    async content(event, trigger, player) {
      const result = await player.chooseCardTarget({
        filterCard(card, player2) {
          return get.suit(card) == "heart" && lib.filter.cardDiscardable(card, player2);
        },
        filterTarget(card, player2, target2) {
          return player2 != target2;
        },
        position: "he",
        ai1(card) {
          return 10 - get.value(card);
        },
        ai2(target2) {
          var att = get.attitude(_status.event.player, target2);
          var trigger2 = _status.event.getTrigger();
          var da = 0;
          if (_status.event.player.hp == 1) {
            da = 10;
          }
          var eff = get.damageEffect(target2, trigger2.source, target2);
          if (att == 0) {
            return 0.1 + da;
          }
          if (eff >= 0 && att > 0) {
            return att + da;
          }
          if (att > 0 && target2.hp > 1) {
            if (target2.maxHp - target2.hp >= 3) {
              return att * 1.1 + da;
            }
            if (target2.maxHp - target2.hp >= 2) {
              return att * 0.9 + da;
            }
          }
          return -att + da;
        },
        prompt: get.prompt("oltianxiang"),
        prompt2: lib.translate.oltianxiang_info
      }).forResult();
      if (result.bool) {
        await player.discard(result.cards);
        var target = result.targets[0];
        const result2 = await player.chooseControlList(
          true,
          function(event2, player2) {
            var target2 = _status.event.target;
            var att = get.attitude(player2, target2);
            if (target2.hasSkillTag("maihp")) {
              att = -att;
            }
            if (att > 0) {
              return 0;
            } else {
              return 1;
            }
          },
          ["令" + get.translation(target) + "受到伤害来源对其造成的1点伤害，然后摸X张牌（X为其已损失体力值且至多为5）", "令" + get.translation(target) + "失去1点体力，然后获得" + get.translation(result.cards)]
        ).set("target", target).forResult();
        player.logSkill(event.name, target);
        trigger.cancel();
        event.target = target;
        event.card = result.cards[0];
        if (typeof result2.index == "number") {
          event.index = result2.index;
          if (result2.index) {
            event.related = event.target.loseHp();
          } else {
            const param = trigger.source ? { source: trigger.source, nocard: true } : { nosource: true, nocard: true };
            event.related = event.target.damage(param);
          }
          await event.related;
        } else {
          return;
        }
        if (event.related.cancelled || target.isDead()) {
          return;
        }
        if (event.index && event.card.isInPile()) {
          await target.gain(event.card, "gain2");
        } else if (target.getDamagedHp()) {
          await target.draw({ num: Math.min(5, target.getDamagedHp()) });
        }
      }
    },
    ai: {
      maixie_defend: true,
      effect: {
        target(card, player, target) {
          if (player.hasSkillTag("jueqing", false, target)) {
            return;
          }
          if (get.tag(card, "damage") && target.countCards("he") > 1) {
            return 0.7;
          }
        }
      }
    }
  }

standard:liuli.code:
{
    audio: 2,
    audioname: ["re_daqiao", "daxiaoqiao"],
    trigger: { target: "useCardToTarget" },
    preHidden: true,
    filter(event, player) {
      if (event.card.name !== "sha") {
        return false;
      }
      if (!player.hasCards("he")) {
        return false;
      }
      return game.hasPlayer((current) => {
        return player.inRange(current) && current !== event.player && current !== player && !!lib.filter.targetEnabled(event.card, event.player, current);
      });
    },
    async cost(event, trigger, player) {
      event.result = await player.chooseCardTarget({
        filterTarget(card, player2, target) {
          const trigger2 = _status.event;
          if (player2.inRange(target) && target != trigger2.source) {
            if (lib.filter.targetEnabled(trigger2.card, trigger2.source, target)) {
              return true;
            }
          }
          return false;
        },
        filterCard: lib.filter.cardDiscardable,
        position: "he",
        ai1: (card) => get.unuseful(card) + 9,
        ai2: (target) => {
          const player2 = get.player();
          if (player2.hasCards("h", "shan")) {
            return -get.attitude(player2, target);
          }
          if (get.attitude(player2, target) < 5) {
            return 6 - get.attitude(player2, target);
          }
          if (player2.hp == 1 && !player2.hasCards("h", "shan")) {
            return 10 - get.attitude(player2, target);
          }
          if (player2.hp == 2 && !player2.hasCards("h", "shan")) {
            return 8 - get.attitude(player2, target);
          }
          return -1;
        },
        prompt: get.prompt(event.skill),
        prompt2: "弃置一张牌，将此【杀】转移给攻击范围内的一名其他角色",
        source: trigger.player,
        card: trigger.card
      }).setHiddenSkill(event.name.slice(0, -5)).forResult();
    },
    async content(event, trigger, player) {
      const target = event.targets[0];
      const evt = trigger.getParent();
      if (evt) {
        evt.triggeredTargets2.remove(player);
        evt.targets.remove(player);
        evt.targets.push(target);
        await player.discard({ cards: event.cards });
      } else {
        throw new ReferenceError("找不到触发【流离】的使用牌事件");
      }
    },
    ai: {
      effect: {
        target_use(card, player, target) {
          if (!target.hasCards("he")) {
            return;
          }
          if (card.name !== "sha") {
            return;
          }
          let min = 1;
          const friend = get.attitude(player, target) > 0;
          const vcard = { name: "shacopy", nature: card.nature, suit: card.suit };
          const players = game.filterPlayer();
          for (const current of players) {
            if (player != current && get.attitude(target, current) < 0 && target.canUse(card, current)) {
              if (!friend) {
                return 0;
              }
              if (get.effect(current, vcard, player, player) > 0) {
                if (!player.canUse(card, players[0])) {
                  return [0, 0.1];
                }
                min = 0;
              }
            }
          }
          return min;
        }
      }
    }
  }

