sp:bingzheng.code:
{
    audio: 2,
    trigger: { player: "phaseUseEnd" },
    direct: true,
    async content(event2, trigger2, player2) {
      const result = await player2.chooseTarget(get.prompt2("bingzheng"), function(card2, player3, target2) {
        return target2.countCards("h") != target2.hp;
      }).set("ai", function(target2) {
        var player3 = _status.event.player;
        var att = get.attitude(player3, target2);
        var nh = target2.countCards("h");
        if (att > 0) {
          if (nh == target2.hp - 1) {
            if (player3 == target2) {
              return att + 1;
            }
            return att + 2;
          }
          if (player3 == target2 && player3.needsToDiscard()) {
            return att / 3;
          }
          return att;
        } else {
          if (nh == target2.hp + 1) {
            return -att;
          }
          if (nh == 0) {
            return 0;
          }
          return -att / 2;
        }
      }).forResult();
      if (result.bool) {
        player2.logSkill("bingzheng", result.targets);
        event2.target = result.targets[0];
      } else {
        event2.finish();
        return;
      }
      let result2;
      if (event2.target.countCards("h")) {
        result2 = await player2.chooseControl(function(event3, player3) {
          var target2 = event3.target;
          if (get.attitude(player3, target2) < 0) {
            return 1;
          }
          return 0;
        }).set("choiceList", ["令" + get.translation(event2.target) + "摸一张牌", "令" + get.translation(event2.target) + "弃置一张手牌"]).forResult();
      } else {
