sp:olshanxi.code:
{
    audio: "shanxi",
    enable: "phaseUse",
    usable: 1,
    filter(event2, player2) {
      return Array.from({ length: 5 }).map((_, i) => i + 1).some((i) => player2.hasEmptySlot(i)) && game.hasPlayer((current) => lib.skill.olshanxi.filterTarget(null, player2, current));
    },
    filterTarget(card2, player2, target2) {
      return target2 != player2 && player2.countCards("h") + target2.countCards("h") > 0 && !player2.inRangeOf(target2);
    },
    async content(event2, trigger2, player2) {
      const target2 = event2.target;
      const cards1 = player2.getCards("h"), cards2 = target2.getCards("h");
      const num = Array.from({ length: 5 }).map((_, i) => i + 1).reduce((sum, i) => sum + player2.countEmptySlot(i), 0);
      const dialog = ["闪袭：选择展示至多" + get.cnNumber(num) + "张牌"];
      if (cards1.length > 0) {
        dialog.push('<div class="text center">你的手牌</div>');
        dialog.push(cards1);
      }
      if (cards2.length > 0) {
        dialog.push('<div class="text center">' + get.translation(target2) + "的手牌</div>");
        if (player2.hasSkillTag("viewHandcard", null, target2, true)) {
          dialog.push(cards2);
        } else {
          dialog.push([cards2.randomSort(), "blank"]);
        }
      }
      const result = await player2.chooseButton(dialog, [1, num], true).set("ai", function(button) {
        var player3 = _status.event.player, target3 = _status.event.getParent().target;
        var card2 = button.link, cards3 = ui.selected.buttons.map((button2) => button2.link);
        var hs = player3.getCards("h"), discard = false;
        for (var i of cards3) {
          if (hs.includes(i)) {
            discard = true;
            break;
          }
        }
        if (hs.includes(card2)) {
          if (discard || get.name(card2) != "shan") {
            return 0;
          }
          if (target3.hasCard((card3) => get.value(card3, target3) > 5, "e")) {
            return 2;
          }
          return 0;
        }
        if (discard && !target3.hasCard(function(cardx) {
          return cardx != card2 && !cards3.includes(cardx) && get.value(cardx, target3) > 0;
        }, "he")) {
          return 0;
        }
        return 1 + Math.random();
      }).forResult();
      let list1 = [], list2 = [];
      if (result.bool) {
        event2.cards = result.links;
        const hs = player2.getCards("h");
        for (const card2 of result.links) {
          if (hs.includes(card2)) {
            list1.push(card2);
          } else {
            list2.push(card2);
          }
        }
        event2.list1 = list1;
        event2.list2 = list2;
        event2.videoId = lib.status.videoId++;
        game.broadcastAll(
          function(player3, target3, list12, list22, id) {
            var dialog2 = ui.create.dialog(player3 + "对" + target3 + "发动了【闪袭】");
            dialog2.videoId = id;
            if (list12.length > 0) {
              dialog2.add('<div class="text center">' + player3 + "展示的牌</div>");
              dialog2.add(list12);
            }
            if (list22.length > 0) {
              dialog2.add('<div class="text center">' + target3 + "被展示的牌</div>");
              dialog2.add(list22);
            }
          },
          get.translation(player2),
          get.translation(target2),
          list1,
          list2,
          event2.videoId
        );
        await game.delay(4);
      } else {
        event2.finish();
        return;
      }
      game.broadcastAll("closeDialog", event2.videoId);
      list1 = event2.list1.filter((card2) => get.name(card2, player2) == "shan");
      list2 = event2.list2.filter((card2) => get.name(card2, target2) == "shan");
      if (list1.length && list2.length) {
        await game.loseAsync({
          lose_list: [
            [player2, list1],
            [target2, list2]
          ],
          discarder: player2
        }).setContent("discardMultiple");
      } else if (list2.length) {
        await target2.discard(list2);
      } else if (list1.length) {
        await player2.discard(list1);
      } else {
        event2.finish();
        return;
      }
      if (target2.hasCard(function(card2) {
        return !event2.cards.includes(card2) && lib.filter.canBeGained(card2, player2, target2);
      }, "he")) {
        await player2.gainPlayerCard(target2, true, "he").set("filterButton", function(button) {
          return !_status.event.cards.includes(button.link);
        }).set("cards", event2.cards);
      }
    },
    ai: {
      order: 14,
      result: {
        target(player2, target2) {
          return -target2.countCards("h");
        }
      }
    }
  }

